use std::path::PathBuf;

/// Sidebar resource groups. Cluster-scoped nodes are the only kind without a namespace.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum ResourceKind {
    Nodes,
    Events,
    Pods,
    Deployments,
    StatefulSets,
    DaemonSets,
    Jobs,
    Services,
    Ingresses,
    ConfigMaps,
    Secrets,
}

impl ResourceKind {
    pub fn title(self) -> &'static str {
        match self {
            Self::Nodes => "Nodes",
            Self::Events => "Events",
            Self::Pods => "Pods",
            Self::Deployments => "Deployments",
            Self::StatefulSets => "StatefulSets",
            Self::DaemonSets => "DaemonSets",
            Self::Jobs => "Jobs",
            Self::Services => "Services",
            Self::Ingresses => "Ingresses",
            Self::ConfigMaps => "ConfigMaps",
            Self::Secrets => "Secrets",
        }
    }

    pub fn supports_metrics(self) -> bool {
        matches!(self, Self::Pods | Self::Nodes)
    }

    pub fn is_secret(self) -> bool {
        matches!(self, Self::Secrets)
    }
}

impl std::fmt::Display for ResourceKind {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.title())
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StatusTone {
    Ok,
    Warn,
    Bad,
    Neutral,
}

#[derive(Clone, Debug)]
pub struct ContextInfo {
    pub name: String,
    pub cluster: String,
    pub namespace: Option<String>,
    pub current: bool,
}

#[derive(Clone, Debug)]
pub struct ResourceRow {
    pub uid: String,
    pub name: String,
    pub namespace: String,
    pub status: String,
    pub tone: StatusTone,
    pub ready: String,
    pub age_secs: u64,
    pub info: String,
    pub labels: Vec<(String, String)>,
    pub cpu_millis: Option<f64>,
    pub cpu_request_millis: Option<f64>,
    pub mem_bytes: Option<f64>,
    pub mem_request_bytes: Option<f64>,
}

#[derive(Clone, Debug)]
pub struct UsageSample {
    pub namespace: String,
    pub name: String,
    pub cpu_millis: f64,
    pub mem_bytes: f64,
}

#[derive(Clone, Debug)]
pub struct ClusterOverview {
    pub context: String,
    pub nodes_ready: u32,
    pub nodes_total: u32,
    pub pods: u32,
    pub warning_events: Option<u32>,
    pub note: Option<String>,
}

pub fn usage_key(namespace: &str, name: &str) -> String {
    format!("{namespace}/{name}")
}

pub fn apply_usage(rows: &mut [ResourceRow], usage: &std::collections::HashMap<String, (f64, f64)>) {
    for row in rows {
        if let Some((cpu, mem)) = usage.get(&usage_key(&row.namespace, &row.name)) {
            row.cpu_millis = Some(*cpu);
            row.mem_bytes = Some(*mem);
        }
    }
}

#[derive(Debug)]
pub enum Command {
    LoadContexts,
    SetKubeconfig { path: PathBuf },
    Connect { context: String },
    SetNamespace { namespace: Option<String> },
    Watch { kind: ResourceKind },
    StopWatch,
    FetchYaml {
        kind: ResourceKind,
        namespace: String,
        name: String,
        uid: String,
        reveal_secrets: bool,
    },
    FetchOverview,
}

#[derive(Debug)]
pub enum AppEvent {
    Contexts(Vec<ContextInfo>),
    Connected {
        context: String,
        namespaces: Vec<String>,
        default_namespace: Option<String>,
    },
    Error(String),
    Rows {
        kind: ResourceKind,
        rows: Vec<ResourceRow>,
    },
    Usage {
        kind: ResourceKind,
        samples: Vec<UsageSample>,
    },
    MetricsUnavailable {
        kind: ResourceKind,
        message: String,
    },
    Yaml { uid: String, yaml: String },
    Overview(ClusterOverview),
}

pub fn format_age(secs: u64) -> String {
    const MIN: u64 = 60;
    const HOUR: u64 = 60 * MIN;
    const DAY: u64 = 24 * HOUR;
    if secs < MIN {
        format!("{secs}s")
    } else if secs < HOUR {
        format!("{}m", secs / MIN)
    } else if secs < DAY {
        format!("{}h", secs / HOUR)
    } else if secs < 365 * DAY {
        format!("{}d", secs / DAY)
    } else {
        format!("{}y", secs / (365 * DAY))
    }
}

pub fn parse_cpu_millis(raw: &str) -> Option<f64> {
    let raw = raw.trim();
    if raw.is_empty() {
        return None;
    }
    if let Some(n) = raw.strip_suffix('n') {
        return parse_f64(n).map(|v| v / 1_000_000.0);
    }
    if let Some(n) = raw.strip_suffix('u') {
        return parse_f64(n).map(|v| v / 1_000.0);
    }
    if let Some(n) = raw.strip_suffix('m') {
        return parse_f64(n);
    }
    parse_f64(raw).map(|cores| cores * 1000.0)
}

pub fn format_cpu(millis: f64) -> String {
    if millis >= 1000.0 {
        let cores = millis / 1000.0;
        if (cores - cores.round()).abs() < 0.05 {
            format!("{cores:.0}")
        } else {
            format!("{cores:.2}")
        }
    } else if millis >= 10.0 {
        format!("{millis:.0}m")
    } else {
        format!("{millis:.1}m")
    }
}

pub fn format_cpu_pair(usage: Option<f64>, request: Option<f64>) -> String {
    match (usage, request) {
        (Some(u), Some(r)) => format!("{} / {}", format_cpu(u), format_cpu(r)),
        (Some(u), None) => format_cpu(u),
        (None, Some(r)) => format!("- / {}", format_cpu(r)),
        (None, None) => "-".to_string(),
    }
}

pub fn parse_bytes(raw: &str) -> Option<f64> {
    let raw = raw.trim();
    if raw.is_empty() {
        return None;
    }
    const UNITS: &[(&str, f64)] = &[
        ("Ki", 1024.0),
        ("Mi", 1024.0 * 1024.0),
        ("Gi", 1024.0 * 1024.0 * 1024.0),
        ("Ti", 1024.0 * 1024.0 * 1024.0 * 1024.0),
        ("Pi", 1024.0 * 1024.0 * 1024.0 * 1024.0 * 1024.0),
        ("Ei", 1024.0 * 1024.0 * 1024.0 * 1024.0 * 1024.0 * 1024.0),
        ("K", 1000.0),
        ("M", 1000.0 * 1000.0),
        ("G", 1000.0 * 1000.0 * 1000.0),
        ("T", 1000.0 * 1000.0 * 1000.0 * 1000.0),
        ("k", 1000.0),
    ];
    for (suffix, mul) in UNITS {
        if let Some(n) = raw.strip_suffix(suffix) {
            return parse_f64(n).map(|v| v * mul);
        }
    }
    parse_f64(raw)
}

pub fn format_bytes(bytes: f64) -> String {
    const UNITS: &[(&str, f64)] = &[
        ("Ti", 1024.0 * 1024.0 * 1024.0 * 1024.0),
        ("Gi", 1024.0 * 1024.0 * 1024.0),
        ("Mi", 1024.0 * 1024.0),
        ("Ki", 1024.0),
    ];
    for (suffix, mul) in UNITS {
        if bytes >= *mul {
            let v = bytes / mul;
            if v >= 10.0 {
                return format!("{v:.0}{suffix}");
            }
            return format!("{v:.1}{suffix}");
        }
    }
    format!("{bytes:.0}B")
}

pub fn format_bytes_pair(usage: Option<f64>, request: Option<f64>) -> String {
    match (usage, request) {
        (Some(u), Some(r)) => format!("{} / {}", format_bytes(u), format_bytes(r)),
        (Some(u), None) => format_bytes(u),
        (None, Some(r)) => format!("- / {}", format_bytes(r)),
        (None, None) => "-".to_string(),
    }
}

fn parse_f64(raw: &str) -> Option<f64> {
    let n: f64 = raw.trim().parse().ok()?;
    n.is_finite().then_some(n)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_cpu() {
        assert_eq!(parse_cpu_millis("1"), Some(1000.0));
        assert_eq!(parse_cpu_millis("500m"), Some(500.0));
        assert_eq!(parse_cpu_millis("1000u"), Some(1.0));
        assert_eq!(parse_cpu_millis("1000000n"), Some(1.0));
    }

    #[test]
    fn parses_memory() {
        assert_eq!(parse_bytes("1024"), Some(1024.0));
        assert_eq!(parse_bytes("1Ki"), Some(1024.0));
        assert_eq!(parse_bytes("1Mi"), Some(1024.0 * 1024.0));
        assert_eq!(parse_bytes("1.5Gi"), Some(1.5 * 1024.0 * 1024.0 * 1024.0));
    }

    #[test]
    fn formats_age_units() {
        assert_eq!(format_age(12), "12s");
        assert_eq!(format_age(120), "2m");
        assert_eq!(format_age(7200), "2h");
        assert_eq!(format_age(3 * 24 * 3600), "3d");
    }

    #[test]
    fn formats_pairs() {
        assert_eq!(format_cpu_pair(Some(250.0), Some(500.0)), "250m / 500m");
        assert_eq!(format_cpu_pair(None, None), "-");
        assert_eq!(format_bytes_pair(Some(1024.0 * 1024.0), None), "1.0Mi");
    }
}

use serde_json::{Map, Value};

/// Read-only YAML for the detail panel. `mask_secret` replaces Secret `data` / `stringData`.
pub fn object_to_yaml(
    mut value: Value,
    api_version: &str,
    kind: &str,
    mask_secret: bool,
) -> Result<String, String> {
    if let Some(meta) = value.get_mut("metadata").and_then(Value::as_object_mut) {
        meta.remove("managedFields");
    }
    if mask_secret {
        mask_map(value.get_mut("data"));
        mask_map(value.get_mut("stringData"));
    }

    let mut ordered = Map::new();
    ordered.insert("apiVersion".to_string(), Value::String(api_version.to_string()));
    ordered.insert("kind".to_string(), Value::String(kind.to_string()));
    if let Some(obj) = value.as_object() {
        for (key, item) in obj {
            if key == "apiVersion" || key == "kind" {
                continue;
            }
            ordered.insert(key.clone(), item.clone());
        }
    }
    serde_yaml::to_string(&Value::Object(ordered)).map_err(|err| err.to_string())
}

fn mask_map(slot: Option<&mut Value>) {
    let Some(Value::Object(map)) = slot else {
        return;
    };
    for value in map.values_mut() {
        *value = Value::String("*****".to_string());
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn masks_secret_and_strips_managed_fields() {
        let value = json!({
            "metadata": {"name": "db", "managedFields": [{"manager": "kubectl"}]},
            "data": {"password": "REDACTED"},
            "stringData": {"token": "abc"}
        });
        let yaml = object_to_yaml(value, "v1", "Secret", true).unwrap();
        assert!(yaml.contains("apiVersion: v1"));
        assert!(yaml.contains("kind: Secret"));
        assert!(yaml.contains("*****"));
        assert!(!yaml.contains("REDACTED"));
        assert!(!yaml.contains("abc"));
        assert!(!yaml.contains("managedFields"));
    }

    #[test]
    fn reveal_keeps_secret_data() {
        let value = json!({"data": {"password": "REDACTED"}});
        let yaml = object_to_yaml(value, "v1", "Secret", false).unwrap();
        assert!(yaml.contains("REDACTED"));
    }
}

use std::path::Path;

use kube::config::{Kubeconfig, NamedContext};

use crate::model::ContextInfo;

pub fn load_kubeconfig(path: Option<&Path>) -> Result<Kubeconfig, String> {
    match path {
        Some(path) => Kubeconfig::read_from(path)
            .map_err(|err| format!("read {}: {err}", path.display())),
        None => Kubeconfig::read().map_err(|err| format!("read kubeconfig: {err}")),
    }
}

pub fn contexts_from(kubeconfig: &Kubeconfig) -> Vec<ContextInfo> {
    let current = kubeconfig.current_context.as_deref();
    kubeconfig
        .contexts
        .iter()
        .map(|named| context_info(named, current))
        .collect()
}

pub fn namespace_of(kubeconfig: &Kubeconfig, context: &str) -> Option<String> {
    kubeconfig
        .contexts
        .iter()
        .find(|named| named.name == context)
        .and_then(|named| named.context.as_ref())
        .and_then(|ctx| ctx.namespace.clone())
        .filter(|ns| !ns.is_empty())
}

fn context_info(named: &NamedContext, current: Option<&str>) -> ContextInfo {
    let (cluster, namespace) = named
        .context
        .as_ref()
        .map(|ctx| (ctx.cluster.clone(), ctx.namespace.clone()))
        .unwrap_or_else(|| (String::new(), None));
    ContextInfo {
        name: named.name.clone(),
        cluster,
        namespace: namespace.filter(|ns| !ns.is_empty()),
        current: current == Some(named.name.as_str()),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reads_contexts_from_a_file() {
        let path = std::env::temp_dir().join(format!("kubi-kubeconfig-{}", std::process::id()));
        std::fs::write(
            &path,
            r#"
apiVersion: v1
kind: Config
current-context: dev
clusters:
- name: dev-cluster
  cluster:
    server: https://127.0.0.1:6443
users:
- name: dev-user
  user:
    token: fake-token
contexts:
- name: dev
  context:
    cluster: dev-cluster
    user: dev-user
    namespace: apps
- name: prod
  context:
    cluster: dev-cluster
    user: dev-user
"#,
        )
        .unwrap();

        let kc = load_kubeconfig(Some(&path)).unwrap();
        let contexts = contexts_from(&kc);
        assert_eq!(contexts.len(), 2);
        assert!(contexts[0].current);
        assert_eq!(contexts[0].name, "dev");
        assert_eq!(contexts[0].cluster, "dev-cluster");
        assert_eq!(contexts[0].namespace.as_deref(), Some("apps"));
        assert!(!contexts[1].current);
        assert_eq!(namespace_of(&kc, "dev").as_deref(), Some("apps"));
        assert_eq!(namespace_of(&kc, "prod"), None);
        let _ = std::fs::remove_file(path);
    }
}

use std::collections::BTreeMap;

use k8s_openapi::api::apps::v1::{DaemonSet, Deployment, StatefulSet};
use k8s_openapi::api::batch::v1::Job;
use k8s_openapi::api::core::v1::{
    ConfigMap, Event, Node, Pod, Secret, Service,
};
use k8s_openapi::api::metrics::v1beta1::{NodeMetrics, PodMetrics};
use k8s_openapi::api::networking::v1::Ingress;
use k8s_openapi::apimachinery::pkg::api::resource::Quantity;
use k8s_openapi::apimachinery::pkg::apis::meta::v1::{ObjectMeta, Time};
use kube::ResourceExt;

use crate::model::{ResourceRow, StatusTone, UsageSample};
use crate::quantity::{parse_bytes, parse_cpu_millis};

pub(crate) fn pod_row(pod: &Pod) -> ResourceRow {
    let (status, tone) = pod_status(pod);
    let ready = pod_ready(pod);
    let (cpu_req, mem_req) = pod_requests(pod);
    let restarts = pod
        .status
        .as_ref()
        .and_then(|status| status.container_statuses.as_ref())
        .map(|statuses| statuses.iter().map(|cs| cs.restart_count).sum::<i32>())
        .unwrap_or(0);
    let node = pod
        .spec
        .as_ref()
        .and_then(|spec| spec.node_name.clone())
        .unwrap_or_else(|| "-".to_string());
    let mut row = make_row(
        &pod.metadata,
        status,
        tone,
        ready,
        format!("{restarts} restarts · {node}"),
        cpu_req,
        mem_req,
    );
    let _ = pod.name_any();
    row
}

pub(crate) fn deployment_row(item: &Deployment) -> ResourceRow {
    let desired = item.spec.as_ref().and_then(|spec| spec.replicas).unwrap_or(0);
    let ready = item.status.as_ref().and_then(|status| status.ready_replicas).unwrap_or(0);
    let (status, tone, ready_col) = replica_status(ready, desired);
    make_row(&item.metadata, status, tone, ready_col, String::new(), None, None)
}

pub(crate) fn statefulset_row(item: &StatefulSet) -> ResourceRow {
    let desired = item.spec.as_ref().and_then(|spec| spec.replicas).unwrap_or(0);
    let ready = item.status.as_ref().and_then(|status| status.ready_replicas).unwrap_or(0);
    let (status, tone, ready_col) = replica_status(ready, desired);
    make_row(&item.metadata, status, tone, ready_col, String::new(), None, None)
}

pub(crate) fn daemonset_row(item: &DaemonSet) -> ResourceRow {
    let desired = item
        .status
        .as_ref()
        .and_then(|status| status.desired_number_scheduled)
        .unwrap_or(0);
    let ready = item.status.as_ref().and_then(|status| status.number_ready).unwrap_or(0);
    let (status, tone, ready_col) = replica_status(ready, desired);
    make_row(&item.metadata, status, tone, ready_col, String::new(), None, None)
}

pub(crate) fn job_row(item: &Job) -> ResourceRow {
    let completions = item.spec.as_ref().and_then(|spec| spec.completions).unwrap_or(1);
    let succeeded = item.status.as_ref().and_then(|status| status.succeeded).unwrap_or(0);
    let failed = item.status.as_ref().and_then(|status| status.failed).unwrap_or(0);
    let (status, tone) = if failed > 0 && succeeded < completions {
        ("Failed".to_string(), StatusTone::Bad)
    } else if succeeded >= completions {
        ("Complete".to_string(), StatusTone::Ok)
    } else {
        ("Running".to_string(), StatusTone::Warn)
    };
    make_row(
        &item.metadata,
        status,
        tone,
        format!("{succeeded}/{completions}"),
        if failed > 0 { format!("{failed} failed") } else { String::new() },
        None,
        None,
    )
}

pub(crate) fn node_row(node: &Node) -> ResourceRow {
    let (status, tone) = node_status(node);
    let (cpu_alloc, mem_alloc) = node_allocatable(node);
    let version = node
        .status
        .as_ref()
        .and_then(|status| status.node_info.as_ref())
        .map(|info| info.kubelet_version.clone())
        .unwrap_or_else(|| "-".to_string());
    make_row(
        &node.metadata,
        status,
        tone,
        version,
        node_roles(node),
        cpu_alloc,
        mem_alloc,
    )
}

pub(crate) fn event_row(event: &Event) -> ResourceRow {
    let kind = event.involved_object.kind.as_deref().unwrap_or("Object");
    let involved = event
        .involved_object
        .name
        .clone()
        .unwrap_or_else(|| event.name_any());
    let reason = event.reason.clone().unwrap_or_default();
    let message = event.message.clone().unwrap_or_default();
    let ty = event.type_.clone().unwrap_or_else(|| "Normal".to_string());
    let tone = if ty == "Warning" { StatusTone::Warn } else { StatusTone::Neutral };
    let count = event.count.unwrap_or(1);
    let mut row = make_row(
        &event.metadata,
        ty,
        tone,
        count.to_string(),
        truncate(&format!("{kind}/{involved} · {reason}: {message}"), 160),
        None,
        None,
    );
    if let Some(ts) = event.last_timestamp.as_ref() {
        row.age_secs = time_age(ts);
    }
    row.name = involved;
    row
}

pub(crate) fn service_row(service: &Service) -> ResourceRow {
    let ty = service
        .spec
        .as_ref()
        .and_then(|spec| spec.type_.clone())
        .unwrap_or_else(|| "ClusterIP".to_string());
    let ip = service
        .spec
        .as_ref()
        .and_then(|spec| spec.cluster_ip.clone())
        .unwrap_or_else(|| "-".to_string());
    let ports = service
        .spec
        .as_ref()
        .and_then(|spec| spec.ports.as_ref())
        .map(|ports| {
            ports
                .iter()
                .map(|port| {
                    let proto = port.protocol.as_deref().unwrap_or("TCP");
                    format!("{}/{}", port.port, proto)
                })
                .collect::<Vec<_>>()
                .join(", ")
        })
        .unwrap_or_default();
    make_row(
        &service.metadata,
        ty,
        StatusTone::Ok,
        ip,
        ports,
        None,
        None,
    )
}

pub(crate) fn ingress_row(ingress: &Ingress) -> ResourceRow {
    let class = ingress
        .spec
        .as_ref()
        .and_then(|spec| spec.ingress_class_name.clone())
        .unwrap_or_else(|| "-".to_string());
    let hosts = ingress
        .spec
        .as_ref()
        .and_then(|spec| spec.rules.as_ref())
        .map(|rules| {
            rules
                .iter()
                .filter_map(|rule| rule.host.clone())
                .collect::<Vec<_>>()
                .join(", ")
        })
        .unwrap_or_default();
    let (status, tone) = if hosts.is_empty() {
        ("Pending".to_string(), StatusTone::Warn)
    } else {
        ("Ready".to_string(), StatusTone::Ok)
    };
    make_row(&ingress.metadata, status, tone, class, hosts, None, None)
}

pub(crate) fn configmap_row(item: &ConfigMap) -> ResourceRow {
    let mut keys = Vec::new();
    if let Some(data) = &item.data {
        keys.extend(data.keys().cloned());
    }
    if let Some(data) = &item.binary_data {
        keys.extend(data.keys().cloned());
    }
    keys.sort();
    let count = keys.len();
    make_row(
        &item.metadata,
        "Active".to_string(),
        StatusTone::Neutral,
        count.to_string(),
        if keys.is_empty() { "empty".to_string() } else { keys.join(", ") },
        None,
        None,
    )
}

pub(crate) fn secret_row(item: &Secret) -> ResourceRow {
    let mut keys = Vec::new();
    if let Some(data) = &item.data {
        keys.extend(data.keys().cloned());
    }
    if let Some(data) = &item.string_data {
        keys.extend(data.keys().cloned());
    }
    keys.sort();
    let ty = item.type_.clone().unwrap_or_else(|| "Opaque".to_string());
    make_row(
        &item.metadata,
        ty,
        StatusTone::Neutral,
        keys.len().to_string(),
        if keys.is_empty() { "no keys".to_string() } else { keys.join(", ") },
        None,
        None,
    )
}

pub(crate) fn pod_usage(metrics: &PodMetrics) -> Option<UsageSample> {
    let name = metrics.metadata.name.clone()?;
    let namespace = metrics.metadata.namespace.clone().unwrap_or_default();
    let (cpu_millis, mem_bytes) = sum_usage(metrics.containers.iter().map(|container| &container.usage));
    Some(UsageSample {
        namespace,
        name,
        cpu_millis,
        mem_bytes,
    })
}

pub(crate) fn node_usage(metrics: &NodeMetrics) -> Option<UsageSample> {
    let name = metrics.metadata.name.clone()?;
    let (cpu_millis, mem_bytes) = sum_quantities(&metrics.usage);
    Some(UsageSample {
        namespace: String::new(),
        name,
        cpu_millis,
        mem_bytes,
    })
}

pub(crate) fn node_is_ready(node: &Node) -> bool {
    matches!(node_status(node).1, StatusTone::Ok)
}

fn make_row(
    meta: &ObjectMeta,
    mut status: String,
    mut tone: StatusTone,
    ready: String,
    info: String,
    cpu_request_millis: Option<f64>,
    mem_request_bytes: Option<f64>,
) -> ResourceRow {
    if meta.deletion_timestamp.is_some() {
        status = "Terminating".to_string();
        tone = StatusTone::Warn;
    }
    let name = meta.name.clone().unwrap_or_default();
    let namespace = meta.namespace.clone().unwrap_or_default();
    let uid = meta.uid.clone().unwrap_or_else(|| format!("{namespace}/{name}"));
    ResourceRow {
        uid,
        name,
        namespace,
        status,
        tone,
        ready,
        age_secs: meta_age(meta),
        info,
        labels: labels_of(meta),
        cpu_millis: None,
        cpu_request_millis,
        mem_bytes: None,
        mem_request_bytes,
    }
}

fn labels_of(meta: &ObjectMeta) -> Vec<(String, String)> {
    let mut labels: Vec<_> = meta
        .labels
        .iter()
        .flat_map(|labels| labels.iter())
        .map(|(key, value)| (key.clone(), value.clone()))
        .collect();
    labels.sort();
    labels
}

fn meta_age(meta: &ObjectMeta) -> u64 {
    meta.creation_timestamp.as_ref().map(time_age).unwrap_or(0)
}

fn time_age(ts: &Time) -> u64 {
    let then = ts.0.as_second();
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_secs() as i64)
        .unwrap_or(0);
    now.saturating_sub(then).max(0) as u64
}

fn pod_status(pod: &Pod) -> (String, StatusTone) {
    if let Some(status) = &pod.status {
        if let Some(statuses) = &status.container_statuses {
            for container in statuses {
                if let Some(reason) = container
                    .state
                    .as_ref()
                    .and_then(|state| state.waiting.as_ref())
                    .and_then(|waiting| waiting.reason.clone())
                {
                    let tone = match reason.as_str() {
                        "ContainerCreating" | "PodInitializing" => StatusTone::Warn,
                        _ => StatusTone::Bad,
                    };
                    return (reason, tone);
                }
            }
        }
        if let Some(phase) = &status.phase {
            let tone = match phase.as_str() {
                "Running" | "Succeeded" => StatusTone::Ok,
                "Pending" => StatusTone::Warn,
                "Failed" | "Unknown" => StatusTone::Bad,
                _ => StatusTone::Neutral,
            };
            return (phase.clone(), tone);
        }
    }
    ("Unknown".to_string(), StatusTone::Neutral)
}

fn pod_ready(pod: &Pod) -> String {
    match pod
        .status
        .as_ref()
        .and_then(|status| status.container_statuses.as_ref())
    {
        Some(statuses) if !statuses.is_empty() => {
            let ready = statuses.iter().filter(|container| container.ready).count();
            format!("{ready}/{}", statuses.len())
        }
        _ => "-".to_string(),
    }
}

fn pod_requests(pod: &Pod) -> (Option<f64>, Option<f64>) {
    let mut cpu = 0.0;
    let mut mem = 0.0;
    let mut any_cpu = false;
    let mut any_mem = false;
    let Some(spec) = &pod.spec else {
        return (None, None);
    };
    for container in &spec.containers {
        let Some(requests) = container.resources.as_ref().and_then(|res| res.requests.as_ref()) else {
            continue;
        };
        if let Some(value) = requests.get("cpu").and_then(|qty| parse_cpu_millis(qty_str(qty))) {
            cpu += value;
            any_cpu = true;
        }
        if let Some(value) = requests.get("memory").and_then(|qty| parse_bytes(qty_str(qty))) {
            mem += value;
            any_mem = true;
        }
    }
    (any_cpu.then_some(cpu), any_mem.then_some(mem))
}

fn node_status(node: &Node) -> (String, StatusTone) {
    let ready = node
        .status
        .as_ref()
        .and_then(|status| status.conditions.as_ref())
        .and_then(|conditions| {
            conditions
                .iter()
                .find(|condition| condition.type_ == "Ready")
                .map(|condition| condition.status.as_str())
        });
    match ready {
        Some("True") => ("Ready".to_string(), StatusTone::Ok),
        Some("False") => ("NotReady".to_string(), StatusTone::Bad),
        Some(_) => ("Unknown".to_string(), StatusTone::Warn),
        None => ("Unknown".to_string(), StatusTone::Neutral),
    }
}

fn node_roles(node: &Node) -> String {
    let mut roles = Vec::new();
    if let Some(labels) = &node.metadata.labels {
        for key in labels.keys() {
            if let Some(role) = key.strip_prefix("node-role.kubernetes.io/") {
                if !role.is_empty() {
                    roles.push(role.to_string());
                }
            }
        }
    }
    roles.sort();
    if roles.is_empty() {
        "worker".to_string()
    } else {
        roles.join(", ")
    }
}

fn node_allocatable(node: &Node) -> (Option<f64>, Option<f64>) {
    let Some(allocatable) = node.status.as_ref().and_then(|status| status.allocatable.as_ref()) else {
        return (None, None);
    };
    (
        allocatable.get("cpu").and_then(|qty| parse_cpu_millis(qty_str(qty))),
        allocatable.get("memory").and_then(|qty| parse_bytes(qty_str(qty))),
    )
}

fn replica_status(ready: i32, desired: i32) -> (String, StatusTone, String) {
    let column = format!("{ready}/{desired}");
    if desired == 0 {
        ("Scaled to 0".to_string(), StatusTone::Neutral, column)
    } else if ready >= desired {
        ("Ready".to_string(), StatusTone::Ok, column)
    } else if ready == 0 {
        ("Unavailable".to_string(), StatusTone::Bad, column)
    } else {
        ("Progressing".to_string(), StatusTone::Warn, column)
    }
}

fn sum_usage<'a>(maps: impl Iterator<Item = &'a BTreeMap<String, Quantity>>) -> (f64, f64) {
    let mut cpu = 0.0;
    let mut mem = 0.0;
    for usage in maps {
        let (cpu_part, mem_part) = sum_quantities(usage);
        cpu += cpu_part;
        mem += mem_part;
    }
    (cpu, mem)
}

fn sum_quantities(usage: &BTreeMap<String, Quantity>) -> (f64, f64) {
    let cpu = usage
        .get("cpu")
        .and_then(|qty| parse_cpu_millis(qty_str(qty)))
        .unwrap_or(0.0);
    let mem = usage
        .get("memory")
        .and_then(|qty| parse_bytes(qty_str(qty)))
        .unwrap_or(0.0);
    (cpu, mem)
}

fn qty_str(qty: &Quantity) -> &str {
    qty.0.as_str()
}

fn truncate(text: &str, max_chars: usize) -> String {
    let count = text.chars().count();
    if count <= max_chars {
        text.to_string()
    } else {
        let trimmed: String = text.chars().take(max_chars).collect();
        format!("{trimmed}…")
    }
}

