use std::path::{Path, PathBuf};
use std::time::Duration;

use futures::StreamExt;
use k8s_openapi::api::apps::v1::{DaemonSet, Deployment, StatefulSet};
use k8s_openapi::api::batch::v1::Job;
use k8s_openapi::api::core::v1::{ConfigMap, Event, Namespace, Node, Pod, Secret, Service};
use k8s_openapi::api::metrics::v1beta1::{NodeMetrics, PodMetrics};
use k8s_openapi::api::networking::v1::Ingress;
use kube::api::{ListParams, ObjectList};
use kube::config::{KubeConfigOptions, Kubeconfig};
use kube::runtime::watcher::{self, watcher, Event};
use kube::{Api, Client, Resource};
use serde::de::DeserializeOwned;
use serde::Serialize;
use tokio::sync::mpsc::{UnboundedReceiver, UnboundedSender};
use tokio_util::sync::CancellationToken;

use crate::kubeconfig::{self, contexts_from, load_kubeconfig, namespace_of};
use crate::model::{AppEvent, ClusterOverview, Command, ResourceKind, UsageSample};
use crate::rows::{
    self, configmap_row, daemonset_row, deployment_row, event_row, ingress_row, job_row, node_is_ready,
    node_row, node_usage, pod_row, pod_usage, secret_row, service_row, statefulset_row,
};
use crate::yaml;

pub struct CoreHandle {
    cmd_tx: UnboundedSender<Command>,
    event_rx: std::sync::mpsc::Receiver<AppEvent>,
}

impl CoreHandle {
    pub fn spawn() -> Self {
        let (cmd_tx, cmd_rx) = tokio::sync::mpsc::unbounded_channel();
        let (event_tx, event_rx) = std::sync::mpsc::channel();
        std::thread::Builder::new()
            .name("kubi-core".into())
            .spawn(move || {
                let runtime = tokio::runtime::Builder::new_multi_thread()
                    .enable_all()
                    .build()
                    .expect("failed to start tokio runtime");
                runtime.block_on(async move {
                    let mut engine = Engine::new(event_tx);
                    let mut cmd_rx = cmd_rx;
                    while let Some(command) = cmd_rx.recv().await {
                        engine.handle(command).await;
                    }
                });
            })
            .expect("failed to start kubi-core thread");
        Self { cmd_tx, event_rx }
    }

    pub fn send(&self, command: Command) {
        let _ = self.cmd_tx.send(command);
    }

    pub fn drain(&self) -> Vec<AppEvent> {
        let mut events = Vec::new();
        while let Ok(event) = self.event_rx.try_recv() {
            events.push(event);
        }
        events
    }
}

struct Engine {
    events: std::sync::mpsc::Sender<AppEvent>,
    kubeconfig_path: Option<PathBuf>,
    clients: std::collections::HashMap<String, Client>,
    context: Option<String>,
    namespace: Option<String>,
    watch: Option<CancellationToken>,
}

impl Engine {
    fn new(events: std::sync::mpsc::Sender<AppEvent>) -> Self {
        Self {
            events,
            kubeconfig_path: None,
            clients: std::collections::HashMap::new(),
            context: None,
            namespace: None,
            watch: None,
        }
    }

    async fn handle(&mut self, command: Command) {
        match command {
            Command::LoadContexts => self.emit_contexts(),
            Command::SetKubeconfig { path } => {
                self.stop_watch();
                self.clients.clear();
                self.kubeconfig_path = Some(path);
                self.emit_contexts();
            }
            Command::Connect { context } => self.connect(context).await,
            Command::SetNamespace { namespace } => self.namespace = namespace,
            Command::Watch { kind } => self.start_watch(kind),
            Command::StopWatch => self.stop_watch(),
            Command::FetchYaml {
                kind,
                namespace,
                name,
                uid,
                reveal_secrets,
            } => self.fetch_yaml(kind, &namespace, &name, &uid, reveal_secrets).await,
            Command::FetchOverview => self.fetch_overview(),
        }
    }

    fn emit(&self, event: AppEvent) {
        let _ = self.events.send(event);
    }

    fn emit_error(&self, message: impl Into<String>) {
        self.emit(AppEvent::Error(message.into()));
    }

    fn emit_contexts(&self) {
        match load_kubeconfig(self.kubeconfig_path.as_deref()) {
            Ok(kubeconfig) => self.emit(AppEvent::Contexts(contexts_from(&kubeconfig))),
            Err(err) => self.emit_error(err),
        }
    }

    async fn connect(&mut self, context: String) {
        self.stop_watch();
        let client = match build_client(self.kubeconfig_path.as_deref(), &context).await {
            Ok(client) => client,
            Err(err) => {
                self.emit_error(err);
                return;
            }
        };
        self.clients.insert(context.clone(), client.clone());
        self.context = Some(context.clone());
        let namespaces = match list_namespaces(&client).await {
            Ok(namespaces) => namespaces,
            Err(err) => {
                self.emit_error(err);
                Vec::new()
            }
        };
        let default_namespace = load_kubeconfig(self.kubeconfig_path.as_deref())
            .ok()
            .and_then(|kubeconfig| namespace_of(&kubeconfig, &context));
        self.namespace = default_namespace.clone();
        self.emit(AppEvent::Connected {
            context,
            namespaces,
            default_namespace,
        });
    }

    fn current_client(&self) -> Option<Client> {
        let context = self.context.as_ref()?;
        self.clients.get(context).cloned()
    }

    fn start_watch(&mut self, kind: ResourceKind) {
        let Some(client) = self.current_client() else {
            self.emit_error("Not connected to a cluster");
            return;
        };
        self.stop_watch();
        let cancel = CancellationToken::new();
        self.watch = Some(cancel.clone());
        let namespace = self.namespace.clone();
        let events = self.events.clone();
        match kind {
            ResourceKind::Pods => {
                spawn_watch(namespaced::<Pod>(client.clone(), &namespace), kind, pod_row, cancel.clone(), events.clone());
                spawn_metrics(kind, cancel, events, move || {
                    let client = client.clone();
                    let namespace = namespace.clone();
                    async move {
                        let api = namespaced::<PodMetrics>(client, &namespace);
                        let items = list_all(api).await?;
                        Ok(items.iter().filter_map(pod_usage).collect())
                    }
                });
            }
            ResourceKind::Nodes => {
                spawn_watch(Api::<Node>::all(client.clone()), kind, node_row, cancel.clone(), events.clone());
                spawn_metrics(kind, cancel, events, move || {
                    let client = client.clone();
                    async move {
                        let items = list_all(Api::<NodeMetrics>::all(client)).await?;
                        Ok(items.iter().filter_map(node_usage).collect())
                    }
                });
            }
            ResourceKind::Events => {
                spawn_watch(namespaced::<Event>(client, &namespace), kind, event_row, cancel, events);
            }
            ResourceKind::Deployments => {
                spawn_watch(namespaced::<Deployment>(client, &namespace), kind, deployment_row, cancel, events);
            }
            ResourceKind::StatefulSets => {
                spawn_watch(namespaced::<StatefulSet>(client, &namespace), kind, statefulset_row, cancel, events);
            }
            ResourceKind::DaemonSets => {
                spawn_watch(namespaced::<DaemonSet>(client, &namespace), kind, daemonset_row, cancel, events);
            }
            ResourceKind::Jobs => {
                spawn_watch(namespaced::<Job>(client, &namespace), kind, job_row, cancel, events);
            }
            ResourceKind::Services => {
                spawn_watch(namespaced::<Service>(client, &namespace), kind, service_row, cancel, events);
            }
            ResourceKind::Ingresses => {
                spawn_watch(namespaced::<Ingress>(client, &namespace), kind, ingress_row, cancel, events);
            }
            ResourceKind::ConfigMaps => {
                spawn_watch(namespaced::<ConfigMap>(client, &namespace), kind, configmap_row, cancel, events);
            }
            ResourceKind::Secrets => {
                spawn_watch(namespaced::<Secret>(client, &namespace), kind, secret_row, cancel, events);
            }
        }
    }

    fn stop_watch(&mut self) {
        if let Some(token) = self.watch.take() {
            token.cancel();
        }
    }

    async fn fetch_yaml(
        &self,
        kind: ResourceKind,
        namespace: &str,
        name: &str,
        uid: &str,
        reveal_secrets: bool,
    ) {
        let Some(client) = self.current_client() else {
            self.emit_error("Not connected to a cluster");
            return;
        };
        let result = yaml_for(client, kind, namespace, name, reveal_secrets).await;
        match result {
            Ok(yaml) => self.emit(AppEvent::Yaml {
                uid: uid.to_string(),
                yaml,
            }),
            Err(err) => self.emit_error(err),
        }
    }

    fn fetch_overview(&self) {
        let Some(client) = self.current_client() else {
            return;
        };
        let context = self.context.clone().unwrap_or_default();
        let events = self.events.clone();
        tokio::spawn(async move {
            match overview(&client, context).await {
                Ok(snapshot) => {
                    let _ = events.send(AppEvent::Overview(snapshot));
                }
                Err(err) => {
                    let _ = events.send(AppEvent::Error(err));
                }
            }
        });
    }
}

fn namespaced<K>(client: Client, namespace: &Option<String>) -> Api<K>
where
    K: Resource<DynamicType = ()> + Clone + DeserializeOwned + std::fmt::Debug,
    K::Scope: kube::core::resource::NamespaceResourceScope,
{
    match namespace {
        Some(namespace) => Api::namespaced(client, namespace),
        None => Api::all(client),
    }
}

fn spawn_watch<K>(
    api: Api<K>,
    kind: ResourceKind,
    to_row: fn(&K) -> crate::model::ResourceRow,
    cancel: CancellationToken,
    events: std::sync::mpsc::Sender<AppEvent>,
) where
    K: Resource<DynamicType = ()> + Clone + DeserializeOwned + std::fmt::Debug + Send + Sync + 'static,
{
    tokio::spawn(async move {
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        let reader_cancel = cancel.clone();
        tokio::spawn(async move {
            let mut stream = std::pin::pin!(watcher(api, watcher::Config::default()));
            loop {
                tokio::select! {
                    _ = reader_cancel.cancelled() => break,
                    item = stream.next() => {
                        match item {
                            None => break,
                            Some(item) => {
                                if tx.send(item).is_err() {
                                    break;
                                }
                            }
                        }
                    }
                }
            }
        });

        let mut rows = Vec::new();
        let mut dirty = false;
        let mut deadline = tokio::time::Instant::now();
        loop {
            tokio::select! {
                _ = cancel.cancelled() => break,
                _ = tokio::time::sleep_until(deadline), if dirty => {
                    publish(&events, kind, &rows);
                    dirty = false;
                }
                item = rx.recv() => {
                    let Some(item) = item else { break };
                    match item {
                        Ok(Event::Init) => rows.clear(),
                        Ok(Event::InitApply(object)) => rows.push(to_row(&object)),
                        Ok(Event::InitDone) => {
                            publish(&events, kind, &rows);
                            dirty = false;
                        }
                        Ok(Event::Apply(object)) => {
                            let row = to_row(&object);
                            if let Some(slot) = rows.iter_mut().find(|existing| existing.uid == row.uid) {
                                *slot = row;
                            } else {
                                rows.push(row);
                            }
                            if !dirty {
                                deadline = tokio::time::Instant::now() + Duration::from_millis(200);
                                dirty = true;
                            }
                        }
                        Ok(Event::Delete(object)) => {
                            let row = to_row(&object);
                            rows.retain(|existing| existing.uid != row.uid);
                            if !dirty {
                                deadline = tokio::time::Instant::now() + Duration::from_millis(200);
                                dirty = true;
                            }
                        }
                        Ok(_) => {}
                        Err(err) => {
                            let _ = events.send(AppEvent::Error(format!("watch {kind}: {err}")));
                        }
                    }
                }
            }
        }
    });
}

fn spawn_metrics<F, Fut>(
    kind: ResourceKind,
    cancel: CancellationToken,
    events: std::sync::mpsc::Sender<AppEvent>,
    mut fetch: F,
) where
    F: FnMut() -> Fut + Send + 'static,
    Fut: std::future::Future<Output = Result<Vec<UsageSample>, String>> + Send,
{
    tokio::spawn(async move {
        loop {
            if cancel.is_cancelled() {
                break;
            }
            match fetch().await {
                Ok(samples) => {
                    let _ = events.send(AppEvent::Usage { kind, samples });
                }
                Err(err) if metrics_missing(&err) => {
                    let _ = events.send(AppEvent::MetricsUnavailable { kind, message: err });
                    break;
                }
                Err(err) => {
                    let _ = events.send(AppEvent::Error(format!("metrics: {err}")));
                }
            }
            tokio::select! {
                _ = cancel.cancelled() => break,
                _ = tokio::time::sleep(Duration::from_secs(10)) => {}
            }
        }
    });
}

fn metrics_missing(err: &str) -> bool {
    let lower = err.to_ascii_lowercase();
    lower.contains("notfound")
        || lower.contains("not found")
        || lower.contains("404")
        || lower.contains("metrics.k8s.io")
        || lower.contains("forbidden")
        || lower.contains("403")
}

fn publish(
    events: &std::sync::mpsc::Sender<AppEvent>,
    kind: ResourceKind,
    rows: &[crate::model::ResourceRow],
) {
    let mut rows = rows.to_vec();
    rows.sort_by(|a, b| a.namespace.cmp(&b.namespace).then(a.name.cmp(&b.name)));
    let _ = events.send(AppEvent::Rows { kind, rows });
}

async fn yaml_for(
    client: Client,
    kind: ResourceKind,
    namespace: &str,
    name: &str,
    reveal_secrets: bool,
) -> Result<String, String> {
    match kind {
        ResourceKind::Pods => typed_yaml::<Pod>(client, namespace, name, "v1", "Pod", false).await,
        ResourceKind::Deployments => {
            typed_yaml::<Deployment>(client, namespace, name, "apps/v1", "Deployment", false).await
        }
        ResourceKind::StatefulSets => {
            typed_yaml::<StatefulSet>(client, namespace, name, "apps/v1", "StatefulSet", false).await
        }
        ResourceKind::DaemonSets => {
            typed_yaml::<DaemonSet>(client, namespace, name, "apps/v1", "DaemonSet", false).await
        }
        ResourceKind::Jobs => typed_yaml::<Job>(client, namespace, name, "batch/v1", "Job", false).await,
        ResourceKind::Services => typed_yaml::<Service>(client, namespace, name, "v1", "Service", false).await,
        ResourceKind::Ingresses => {
            typed_yaml::<Ingress>(client, namespace, name, "networking.k8s.io/v1", "Ingress", false).await
        }
        ResourceKind::ConfigMaps => {
            typed_yaml::<ConfigMap>(client, namespace, name, "v1", "ConfigMap", false).await
        }
        ResourceKind::Secrets => {
            typed_yaml::<Secret>(client, namespace, name, "v1", "Secret", !reveal_secrets).await
        }
        ResourceKind::Events => typed_yaml::<Event>(client, namespace, name, "v1", "Event", false).await,
        ResourceKind::Nodes => typed_yaml::<Node>(client, "", name, "v1", "Node", false).await,
    }
}

async fn typed_yaml<K>(
    client: Client,
    namespace: &str,
    name: &str,
    api_version: &str,
    kind: &str,
    mask_secret: bool,
) -> Result<String, String>
where
    K: Resource<DynamicType = ()>
        + Clone
        + DeserializeOwned
        + Serialize
        + std::fmt::Debug
        + Send
        + Sync,
{
    let api: Api<K> = if namespace.is_empty() {
        Api::all(client)
    } else {
        Api::namespaced(client, namespace)
    };
    let object = api.get(name).await.map_err(|err| err.to_string())?;
    let value = serde_json::to_value(&object).map_err(|err| err.to_string())?;
    yaml::object_to_yaml(value, api_version, kind, mask_secret)
}

async fn build_client(path: Option<&Path>, context: &str) -> Result<Client, String> {
    let options = KubeConfigOptions {
        context: Some(context.to_string()),
        cluster: None,
        user: None,
    };
    let config = match path {
        Some(path) => {
            let kubeconfig = Kubeconfig::read_from(path).map_err(|err| err.to_string())?;
            kube::Config::from_custom_kubeconfig(kubeconfig, &options)
                .await
                .map_err(|err| err.to_string())?
        }
        None => kube::Config::from_kubeconfig(&options)
            .await
            .map_err(|err| err.to_string())?,
    };
    Client::try_from(config).map_err(|err| err.to_string())
}

async fn list_namespaces(client: &Client) -> Result<Vec<String>, String> {
    let mut names: Vec<_> = list_all(Api::<Namespace>::all(client.clone()))
        .await?
        .into_iter()
        .filter_map(|namespace| namespace.metadata.name)
        .collect();
    names.sort();
    Ok(names)
}

async fn list_all<K>(api: Api<K>) -> Result<Vec<K>, String>
where
    K: Resource<DynamicType = ()> + Clone + DeserializeOwned + std::fmt::Debug,
{
    let mut params = ListParams::default().limit(500);
    let mut items = Vec::new();
    for _ in 0..200 {
        let page: ObjectList<K> = api.list(&params).await.map_err(|err| err.to_string())?;
        items.extend(page.items);
        let Some(token) = page.metadata.continue_.filter(|token| !token.is_empty()) else {
            break;
        };
        params = ListParams::default().limit(500).continue_token(&token);
    }
    Ok(items)
}

async fn overview(client: &Client, context: String) -> Result<ClusterOverview, String> {
    let nodes = list_all(Api::<Node>::all(client.clone())).await?;
    let pods = list_all(Api::<Pod>::all(client.clone())).await?;
    let events = list_all(Api::<Event>::all(client.clone())).await;
    let nodes_total = nodes.len() as u32;
    let nodes_ready = nodes.iter().filter(|node| node_is_ready(node)).count() as u32;
    let (warning_events, note) = match events {
        Ok(events) => (
            Some(
                events
                    .iter()
                    .filter(|event| event.type_.as_deref() == Some("Warning"))
                    .count() as u32,
            ),
            None,
        ),
        Err(err) => (None, Some(format!("Events unavailable: {err}"))),
    };
    Ok(ClusterOverview {
        context,
        nodes_ready,
        nodes_total,
        pods: pods.len() as u32,
        warning_events,
        note,
    })
}

