use std::collections::{HashMap, VecDeque};
use std::time::{Duration, Instant};

use eframe::egui::{self, Align, Layout, RichText, ScrollArea, Sense, TextEdit, Vec2};
use egui_extras::{Column, TableBuilder};
use egui_plot::{Line, Plot, PlotPoints};
use kubi_core::{
    format_age, format_bytes_pair, format_cpu_pair, usage_key, AppEvent, ClusterOverview, Command, ContextInfo,
    CoreHandle, ResourceKind, ResourceRow, StatusTone, View as _,
};

use crate::theme::{self, tone_color, ACCENT, BAD, MUTED, OK};

const NAV: &[(&str, &[ResourceKind])] = &[
    ("Cluster", &[ResourceKind::Nodes, ResourceKind::Events]),
    (
        "Workloads",
        &[
            ResourceKind::Pods,
            ResourceKind::Deployments,
            ResourceKind::StatefulSets,
            ResourceKind::DaemonSets,
            ResourceKind::Jobs,
        ],
    ),
    ("Network", &[ResourceKind::Services, ResourceKind::Ingresses]),
    ("Config", &[ResourceKind::ConfigMaps, ResourceKind::Secrets]),
];

#[derive(Clone, Copy, PartialEq, Eq)]
enum View {
    Overview,
    Resource(ResourceKind),
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum DetailTab {
    Overview,
    Yaml,
    Metrics,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum SortCol {
    Name,
    Namespace,
    Status,
    Ready,
    Age,
    Cpu,
    Memory,
    Info,
}

struct HistPoint {
    t: f64,
    cpu: f64,
    mem: f64,
}

pub struct KubiApp {
    core: CoreHandle,
    started: Instant,
    contexts: Vec<ContextInfo>,
    context: Option<String>,
    namespaces: Vec<String>,
    namespace: Option<String>,
    namespace_touched: bool,
    view: View,
    rows: Vec<ResourceRow>,
    selected: Option<String>,
    detail_tab: DetailTab,
    yaml: Option<String>,
    yaml_for: Option<String>,
    reveal_secrets: bool,
    error: Option<String>,
    loading_config: bool,
    connecting: bool,
    waiting_rows: bool,
    overview: Option<ClusterOverview>,
    overview_at: Option<Instant>,
    usage: HashMap<String, (f64, f64)>,
    metrics_note: Option<String>,
    history: VecDeque<HistPoint>,
    filter: String,
    sort: SortCol,
    sort_asc: bool,
}

impl KubiApp {
    fn new() -> Self {
        let core = CoreHandle::spawn();
        core.send(Command::LoadContexts);
        Self {
            core,
            started: Instant::now(),
            contexts: Vec::new(),
            context: None,
            namespaces: Vec::new(),
            namespace: None,
            namespace_touched: false,
            view: View::Overview,
            rows: Vec::new(),
            selected: None,
            detail_tab: DetailTab::Overview,
            yaml: None,
            yaml_for: None,
            reveal_secrets: false,
            error: None,
            loading_config: true,
            connecting: false,
            waiting_rows: false,
            overview: None,
            overview_at: None,
            usage: HashMap::new(),
            metrics_note: None,
            history: VecDeque::new(),
            filter: String::new(),
            sort: SortCol::Name,
            sort_asc: true,
        }
    }

    fn resource_kind(&self) -> Option<ResourceKind> {
        match self.view {
            View::Resource(kind) => Some(kind),
            View::Overview => None,
        }
    }

    fn switch_context(&mut self, name: String) {
        if self.context.as_ref() == Some(&name) {
            return;
        }
        self.context = Some(name.clone());
        self.namespace = None;
        self.namespace_touched = false;
        self.connecting = true;
        self.rows.clear();
        self.selected = None;
        self.yaml = None;
        self.overview = None;
        self.usage.clear();
        self.history.clear();
        self.metrics_note = None;
        self.core.send(Command::Connect { context: name });
    }

    fn set_namespace(&mut self, namespace: Option<String>) {
        if self.namespace == namespace {
            return;
        }
        self.namespace = namespace.clone();
        self.namespace_touched = true;
        self.rows.clear();
        self.selected = None;
        self.yaml = None;
        self.usage.clear();
        self.history.clear();
        self.core.send(Command::SetNamespace { namespace });
        self.rewatch();
    }

    fn open_view(&mut self, view: View) {
        if self.view == view {
            return;
        }
        self.view = view;
        self.rows.clear();
        self.selected = None;
        self.yaml = None;
        self.usage.clear();
        self.history.clear();
        self.metrics_note = None;
        self.filter.clear();
        match view {
            View::Overview => {
                self.waiting_rows = false;
                self.core.send(Command::StopWatch);
                self.core.send(Command::FetchOverview);
                self.overview_at = Some(Instant::now());
            }
            View::Resource(_) => self.rewatch(),
        }
    }

    fn rewatch(&mut self) {
        if let View::Resource(kind) = self.view {
            self.waiting_rows = true;
            self.core.send(Command::Watch { kind });
        }
    }

    fn refresh(&mut self) {
        match self.view {
            View::Overview => {
                self.core.send(Command::FetchOverview);
                self.overview_at = Some(Instant::now());
            }
            View::Resource(_) => self.rewatch(),
        }
    }

    fn select(&mut self, uid: String) {
        if self.selected.as_ref() == Some(&uid) {
            return;
        }
        self.selected = Some(uid);
        self.yaml = None;
        self.yaml_for = None;
        self.history.clear();
        self.detail_tab = DetailTab::Overview;
        self.request_yaml();
    }

    fn request_yaml(&mut self) {
        let Some(kind) = self.resource_kind() else {
            return;
        };
        let Some(uid) = self.selected.clone() else {
            return;
        };
        let Some(row) = self.rows.iter().find(|row| row.uid == uid) else {
            return;
        };
        let namespace = row.namespace.clone();
        let name = row.name.clone();
        let uid = row.uid.clone();
        self.core.send(Command::FetchYaml {
            kind,
            namespace,
            name,
            uid,
            reveal_secrets: self.reveal_secrets,
        });
    }

    fn apply_usage(&mut self) {
        kubi_core::apply_usage(&mut self.rows, &self.usage);
    }

    fn push_history(&mut self, namespace: &str, name: &str, cpu: f64, mem: f64) {
        let Some(selected) = self.selected_row() else {
            return;
        };
        if selected.namespace != namespace || selected.name != name {
            return;
        }
        let point = HistPoint {
            t: self.started.elapsed().as_secs_f64(),
            cpu,
            mem,
        };
        if let Some(last) = self.history.back_mut() {
            if point.t - last.t < 1.0 {
                *last = point;
                return;
            }
        }
        self.history.push_back(point);
        while self.history.len() > 60 {
            self.history.pop_front();
        }
    }

    fn selected_row(&self) -> Option<&ResourceRow> {
        let uid = self.selected.as_ref()?;
        self.rows.iter().find(|row| &row.uid == uid)
    }

    fn handle_events(&mut self) {
        for event in self.core.drain() {
            match event {
                AppEvent::Contexts(contexts) => {
                    self.loading_config = false;
                    self.error = None;
                    self.contexts = contexts;
                    if self.contexts.is_empty() {
                        self.connecting = false;
                        continue;
                    }
                    let pick = self
                        .context
                        .clone()
                        .filter(|name| self.contexts.iter().any(|ctx| &ctx.name == name))
                        .or_else(|| {
                            self.contexts
                                .iter()
                                .find(|ctx| ctx.current)
                                .map(|ctx| ctx.name.clone())
                        })
                        .or_else(|| self.contexts.first().map(|ctx| ctx.name.clone()));
                    if let Some(name) = pick {
                        self.context = None;
                        self.switch_context(name);
                    }
                }
                AppEvent::Connected {
                    context,
                    namespaces,
                    default_namespace,
                } => {
                    if self.context.as_ref() != Some(&context) {
                        continue;
                    }
                    self.connecting = false;
                    self.error = None;
                    self.namespaces = namespaces;
                    if !self.namespace_touched {
                        self.namespace = default_namespace;
                    }
                    self.core.send(Command::SetNamespace {
                        namespace: self.namespace.clone(),
                    });
                    self.core.send(Command::FetchOverview);
                    self.overview_at = Some(Instant::now());
                    self.rewatch();
                }
                AppEvent::Error(message) => {
                    self.connecting = false;
                    self.waiting_rows = false;
                    self.loading_config = false;
                    self.error = Some(message);
                }
                AppEvent::Rows { kind, mut rows } => {
                    if self.view != View::Resource(kind) {
                        continue;
                    }
                    kubi_core::apply_usage(&mut rows, &self.usage);
                    self.rows = rows;
                    self.waiting_rows = false;
                    self.error = None;
                }
                AppEvent::Usage { kind, samples } => {
                    if self.resource_kind() != Some(kind) {
                        continue;
                    }
                    self.metrics_note = None;
                    for sample in samples {
                        self.push_history(&sample.namespace, &sample.name, sample.cpu_millis, sample.mem_bytes);
                        self.usage.insert(
                            usage_key(&sample.namespace, &sample.name),
                            (sample.cpu_millis, sample.mem_bytes),
                        );
                    }
                    self.apply_usage();
                }
                AppEvent::MetricsUnavailable { kind, message } => {
                    if self.resource_kind() == Some(kind) {
                        self.metrics_note = Some(format!("Metrics API is not available. {message}"));
                    }
                }
                AppEvent::Yaml { uid, yaml } => {
                    if self.selected.as_ref() == Some(&uid) {
                        self.yaml = Some(yaml);
                        self.yaml_for = Some(uid);
                    }
                }
                AppEvent::Overview(overview) => {
                    if self.context.as_deref() == Some(overview.context.as_str()) {
                        self.overview = Some(overview);
                    }
                }
            }
        }
    }

    fn visible_indices(&self) -> Vec<usize> {
        let needle = self.filter.trim().to_ascii_lowercase();
        let mut indices: Vec<usize> = (0..self.rows.len())
            .filter(|&index| {
                if needle.is_empty() {
                    return true;
                }
                let row = &self.rows[index];
                row.name.to_ascii_lowercase().contains(&needle)
                    || row.namespace.to_ascii_lowercase().contains(&needle)
                    || row.status.to_ascii_lowercase().contains(&needle)
                    || row.info.to_ascii_lowercase().contains(&needle)
            })
            .collect();
        let asc = self.sort_asc;
        let sort = self.sort;
        indices.sort_by(|&a, &b| compare_rows(&self.rows[a], &self.rows[b], sort, asc));
        indices
    }
}

impl eframe::App for KubiApp {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        self.handle_events();
        if self.view == View::Overview
            && self.context.is_some()
            && self.overview_at.is_none_or(|at| at.elapsed() >= Duration::from_secs(15))
        {
            self.core.send(Command::FetchOverview);
            self.overview_at = Some(Instant::now());
        }
        ctx.request_repaint_after(Duration::from_millis(100));

        self.top_bar(ctx);
        self.side_bar(ctx);
        let show_detail = self.selected.is_some() && self.resource_kind().is_some();
        if show_detail {
            self.detail(ctx);
        }
        egui::CentralPanel::default().show(ctx, |ui| match self.view {
            View::Overview => self.overview_view(ui),
            View::Resource(kind) => self.resource_view(ui, kind),
        });
    }
}

impl KubiApp {
    fn top_bar(&mut self, ctx: &egui::Context) {
        egui::TopBottomPanel::top("top").exact_height(52.0).show(ctx, |ui| {
            ui.add_space(6.0);
            ui.horizontal(|ui| {
                ui.label(RichText::new("Kubi").strong().size(18.0).color(ACCENT));
                ui.add_space(12.0);
                self.cluster_combo(ui);
                self.namespace_combo(ui);
                if ui.button("Open kubeconfig").clicked() {
                    if let Some(path) = rfd::FileDialog::new()
                        .set_title("Open kubeconfig")
                        .pick_file()
                    {
                        self.context = None;
                        self.loading_config = true;
                        self.core.send(Command::SetKubeconfig { path });
                    }
                }
                if ui.button("Refresh").clicked() {
                    self.refresh();
                }
            });
            if let Some(err) = self.error.clone() {
                ui.horizontal(|ui| {
                    ui.label(RichText::new(err).color(BAD));
                    if ui.button("Dismiss").clicked() {
                        self.error = None;
                    }
                });
            }
        });
    }

    fn cluster_combo(&mut self, ui: &mut egui::Ui) {
        let names: Vec<String> = self.contexts.iter().map(|ctx| ctx.name.clone()).collect();
        let clusters: Vec<String> = self.contexts.iter().map(|ctx| ctx.cluster.clone()).collect();
        let current = self.context.clone().unwrap_or_else(|| "No cluster".to_string());
        let mut picked = None;
        egui::ComboBox::from_id_salt("cluster")
            .width(240.0)
            .selected_text(&current)
            .show_ui(ui, |ui| {
                for (name, cluster) in names.iter().zip(clusters.iter()) {
                    let label = if cluster.is_empty() {
                        name.clone()
                    } else {
                        format!("{name}  ·  {cluster}")
                    };
                    if ui.selectable_label(self.context.as_ref() == Some(name), label).clicked() {
                        picked = Some(name.clone());
                    }
                }
            });
        if let Some(name) = picked {
            self.switch_context(name);
        }
    }

    fn namespace_combo(&mut self, ui: &mut egui::Ui) {
        let namespaces = self.namespaces.clone();
        let current = self.namespace.clone();
        let label = current.clone().unwrap_or_else(|| "All namespaces".to_string());
        let mut picked: Option<Option<String>> = None;
        egui::ComboBox::from_id_salt("namespace")
            .width(180.0)
            .selected_text(label)
            .show_ui(ui, |ui| {
                if ui.selectable_label(current.is_none(), "All namespaces").clicked() {
                    picked = Some(None);
                }
                for namespace in &namespaces {
                    if ui.selectable_label(current.as_ref() == Some(namespace), namespace).clicked() {
                        picked = Some(Some(namespace.clone()));
                    }
                }
            });
        if let Some(namespace) = picked {
            self.set_namespace(namespace);
        }
    }

    fn side_bar(&mut self, ctx: &egui::Context) {
        let mut next = None;
        egui::SidePanel::left("nav").exact_width(210.0).resizable(false).show(ctx, |ui| {
            ui.add_space(8.0);
            if ui.selectable_label(self.view == View::Overview, "Overview").clicked() {
                next = Some(View::Overview);
            }
            ui.add_space(8.0);
            for (title, kinds) in NAV {
                ui.label(theme::section_label(title));
                for kind in *kinds {
                    let selected = self.view == View::Resource(*kind);
                    if ui.selectable_label(selected, kind.title()).clicked() {
                        next = Some(View::Resource(*kind));
                    }
                }
                ui.add_space(8.0);
            }
        });
        if let Some(view) = next {
            self.open_view(view);
        }
    }

    fn overview_view(&mut self, ui: &mut egui::Ui) {
        ui.add_space(8.0);
        ui.heading("Overview");
        if self.loading_config {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label("Reading kubeconfig…");
            });
            return;
        }
        if self.contexts.is_empty() {
            ui.label("No contexts in kubeconfig. Open a kubeconfig file, or create ~/.kube/config.");
            return;
        }
        if self.connecting {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label("Connecting…");
            });
        }
        let Some(context) = self.context.clone() else {
            ui.label("Select a cluster.");
            return;
        };
        let cluster = self
            .contexts
            .iter()
            .find(|ctx| ctx.name == context)
            .map(|ctx| ctx.cluster.clone())
            .unwrap_or_default();
        ui.label(RichText::new(format!("{context}  ·  {cluster}")).color(MUTED));
        ui.add_space(12.0);
        if let Some(overview) = &self.overview {
            let warnings = overview
                .warning_events
                .map(|count| count.to_string())
                .unwrap_or_else(|| "-".to_string());
            let note = overview.note.clone();
            ui.horizontal(|ui| {
                stat_card(ui, "Nodes ready", &format!("{}/{}", overview.nodes_ready, overview.nodes_total), OK);
                stat_card(ui, "Pods", &overview.pods.to_string(), ACCENT);
                stat_card(ui, "Warning events", &warnings, if overview.warning_events.unwrap_or(0) > 0 { BAD } else { MUTED });
            });
            if let Some(note) = note {
                ui.add_space(8.0);
                ui.label(RichText::new(note).color(MUTED));
            }
        } else if !self.connecting {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label("Loading cluster summary…");
            });
        }
    }

    fn resource_view(&mut self, ui: &mut egui::Ui, kind: ResourceKind) {
        ui.add_space(6.0);
        let count = self.visible_indices().len();
        let mut refresh = false;
        ui.horizontal(|ui| {
            ui.heading(kind.title());
            ui.label(RichText::new(format!("{count}")).color(MUTED));
            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                if ui.button("Refresh").clicked() {
                    refresh = true;
                }
                ui.add(TextEdit::singleline(&mut self.filter).hint_text("Filter").desired_width(200.0));
            });
        });
        if refresh {
            self.refresh();
        }
        if self.connecting || self.waiting_rows && self.rows.is_empty() {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label(if self.connecting { "Connecting…" } else { "Loading…" });
            });
            return;
        }
        if self.rows.is_empty() {
            ui.label("No objects.");
            return;
        }
        self.table(ui, kind);
    }

    fn table(&mut self, ui: &mut egui::Ui, kind: ResourceKind) {
        let indices = self.visible_indices();
        let rows = &self.rows;
        let selected = self.selected.clone();
        let sort = self.sort;
        let asc = self.sort_asc;
        let mut pick = None;
        let mut header_click = None;
        TableBuilder::new(ui)
            .striped(true)
            .resizable(true)
            .cell_layout(Layout::left_to_right(Align::Center))
            .column(Column::initial(220.0).at_least(140.0))
            .column(Column::initial(140.0).at_least(90.0))
            .column(Column::initial(130.0).at_least(90.0))
            .column(Column::initial(90.0).at_least(70.0))
            .column(Column::initial(60.0).at_least(48.0))
            .column(Column::initial(120.0).at_least(80.0))
            .column(Column::initial(120.0).at_least(80.0))
            .column(Column::remainder().at_least(160.0))
            .header(24.0, |mut header| {
                header_click = header_cell(&mut header, "Name", sort, asc, SortCol::Name).or(header_click);
                header_click = header_cell(&mut header, "Namespace", sort, asc, SortCol::Namespace).or(header_click);
                header_click = header_cell(&mut header, "Status", sort, asc, SortCol::Status).or(header_click);
                header_click = header_cell(&mut header, ready_header(kind), sort, asc, SortCol::Ready).or(header_click);
                header_click = header_cell(&mut header, "Age", sort, asc, SortCol::Age).or(header_click);
                header_click = header_cell(&mut header, "CPU", sort, asc, SortCol::Cpu).or(header_click);
                header_click = header_cell(&mut header, "Memory", sort, asc, SortCol::Memory).or(header_click);
                header_click = header_cell(&mut header, "Info", sort, asc, SortCol::Info).or(header_click);
            })
            .body(|mut body| {
                body.rows(24.0, indices.len(), |mut row| {
                    let index = indices[row.index()];
                    let item = &rows[index];
                    let is_selected = selected.as_ref() == Some(&item.uid);
                    row.set_selected(is_selected);
                    let mut hit = false;
                    row.col(|ui| hit |= clickable(ui, RichText::new(&item.name).strong()));
                    row.col(|ui| hit |= clickable(ui, item.namespace.as_str()));
                    row.col(|ui| {
                        ui.horizontal(|ui| {
                            status_dot(ui, item.tone);
                            hit |= clickable(ui, RichText::new(&item.status).color(tone_color(item.tone)));
                        });
                    });
                    row.col(|ui| hit |= clickable(ui, item.ready.as_str()));
                    row.col(|ui| hit |= clickable(ui, format_age(item.age_secs)));
                    row.col(|ui| hit |= clickable(ui, format_cpu_pair(item.cpu_millis, item.cpu_request_millis)));
                    row.col(|ui| hit |= clickable(ui, format_bytes_pair(item.mem_bytes, item.mem_request_bytes)));
                    row.col(|ui| hit |= clickable(ui, item.info.as_str()));
                    if hit {
                        pick = Some(item.uid.clone());
                    }
                });
            });
        if let Some(column) = header_click {
            if self.sort == column {
                self.sort_asc = !self.sort_asc;
            } else {
                self.sort = column;
                self.sort_asc = true;
            }
        }
        if let Some(uid) = pick {
            self.select(uid);
        }
    }

    fn detail(&mut self, ctx: &egui::Context) {
        let kind = self.resource_kind();
        let row = self.selected_row().cloned();
        let Some(row) = row else {
            return;
        };
        let mut reveal_changed = false;
        let mut tab = self.detail_tab;
        egui::SidePanel::right("detail").exact_width(440.0).resizable(true).show(ctx, |ui| {
            ui.add_space(8.0);
            ui.horizontal(|ui| {
                ui.label(RichText::new(&row.name).strong().size(16.0));
                if ui.button("Close").clicked() {
                    tab = DetailTab::Overview;
                    reveal_changed = false;
                }
            });
            ui.label(RichText::new(format!("{}  ·  {}", kind.map(|k| k.title()).unwrap_or(""), row.namespace)).color(MUTED));
            ui.add_space(6.0);
            ui.horizontal(|ui| {
                if ui.selectable_label(tab == DetailTab::Overview, "Overview").clicked() {
                    tab = DetailTab::Overview;
                }
                if ui.selectable_label(tab == DetailTab::Yaml, "YAML").clicked() {
                    tab = DetailTab::Yaml;
                }
                if kind.is_some_and(ResourceKind::supports_metrics)
                    && ui.selectable_label(tab == DetailTab::Metrics, "Metrics").clicked()
                {
                    tab = DetailTab::Metrics;
                }
            });
            ui.separator();
            match tab {
                DetailTab::Overview => overview_tab(ui, &row),
                DetailTab::Yaml => {
                    if kind.is_some_and(ResourceKind::is_secret) {
                        let mut reveal = self.reveal_secrets;
                        if ui.checkbox(&mut reveal, "Show secret values").changed() {
                            self.reveal_secrets = reveal;
                            reveal_changed = true;
                        }
                    }
                    if let Some(yaml) = &self.yaml {
                        if ui.button("Copy").clicked() {
                            ui.ctx().copy_text(yaml.clone());
                        }
                        show_yaml(ui, yaml);
                    } else {
                        ui.horizontal(|ui| {
                            ui.spinner();
                            ui.label("Loading YAML…");
                        });
                    }
                }
                DetailTab::Metrics => self.metrics_tab(ui, &row),
            }
        });
        let close = false;
        // Close is handled inside the panel via a flag we didn't thread. Re-read below.
        let _ = close;
        self.detail_tab = tab;
        if reveal_changed {
            self.yaml = None;
            self.request_yaml();
        }
        let _ = self.yaml_for.as_ref();
    }

    fn metrics_tab(&self, ui: &mut egui::Ui, row: &ResourceRow) {
        if let Some(note) = &self.metrics_note {
            ui.label(note);
            ui.add_space(8.0);
        }
        ui.label(format!(
            "CPU  {}    Memory  {}",
            format_cpu_pair(row.cpu_millis, row.cpu_request_millis),
            format_bytes_pair(row.mem_bytes, row.mem_request_bytes)
        ));
        if self.history.is_empty() {
            ui.label(RichText::new("Waiting for metrics samples…").color(MUTED));
            return;
        }
        let cpu: Vec<[f64; 2]> = self.history.iter().map(|point| [point.t, point.cpu]).collect();
        let mem: Vec<[f64; 2]> = self
            .history
            .iter()
            .map(|point| [point.t, point.mem / (1024.0 * 1024.0)])
            .collect();
        ui.label(RichText::new("CPU (millicores)").color(MUTED));
        Plot::new("cpu")
            .height(150.0)
            .allow_scroll(false)
            .allow_drag(false)
            .show(ui, |plot_ui| {
                plot_ui.line(Line::new("CPU", PlotPoints::new(cpu)).color(ACCENT));
            });
        ui.label(RichText::new("Memory (MiB)").color(MUTED));
        Plot::new("mem")
            .height(150.0)
            .allow_scroll(false)
            .allow_drag(false)
            .show(ui, |plot_ui| {
                plot_ui.line(Line::new("Memory", PlotPoints::new(mem)).color(OK));
            });
        ui.label(
            RichText::new("CPU is usage versus requests. For nodes the second number is allocatable.")
                .small()
                .color(MUTED),
        );
    }
}

fn overview_tab(ui: &mut egui::Ui, row: &ResourceRow) {
    ScrollArea::vertical().show(ui, |ui| {
        meta_line(ui, "Status", &row.status);
        meta_line(ui, "Namespace", if row.namespace.is_empty() { "-" } else { &row.namespace });
        meta_line(ui, "Age", &format_age(row.age_secs));
        if !row.ready.is_empty() && row.ready != "-" {
            meta_line(ui, "Ready", &row.ready);
        }
        if !row.info.is_empty() {
            meta_line(ui, "Info", &row.info);
        }
        ui.add_space(8.0);
        ui.label(theme::section_label("LABELS"));
        if row.labels.is_empty() {
            ui.label(RichText::new("none").color(MUTED));
        } else {
            for (key, value) in row.labels.iter().take(32) {
                ui.label(RichText::new(format!("{key}={value}")).monospace().size(12.0));
            }
            if row.labels.len() > 32 {
                ui.label(RichText::new(format!("… {} more", row.labels.len() - 32)).color(MUTED));
            }
        }
    });
}

fn meta_line(ui: &mut egui::Ui, key: &str, value: &str) {
    ui.horizontal(|ui| {
        ui.label(RichText::new(key).color(MUTED).size(12.0));
        ui.label(value);
    });
}

fn show_yaml(ui: &mut egui::Ui, yaml: &str) {
    ScrollArea::both().auto_shrink([false, false]).show(ui, |ui| {
        for line in yaml.lines() {
            let trimmed = line.trim_start();
            if trimmed.starts_with('#') || trimmed == "---" {
                ui.label(RichText::new(line).monospace().size(12.0).color(MUTED));
                continue;
            }
            if let Some((key, value)) = split_yaml_key(line) {
                ui.horizontal(|ui| {
                    ui.spacing_mut().item_spacing.x = 0.0;
                    ui.label(RichText::new(key).monospace().size(12.0).color(ACCENT));
                    ui.label(RichText::new(value).monospace().size(12.0));
                });
            } else {
                ui.label(RichText::new(line).monospace().size(12.0));
            }
        }
    });
}

fn split_yaml_key(line: &str) -> Option<(&str, &str)> {
    let trimmed = line.trim_start();
    if trimmed.starts_with('-') || trimmed.is_empty() {
        return None;
    }
    let idx = line.find(':')?;
    let (key, value) = line.split_at(idx + 1);
    Some((key, value))
}

fn stat_card(ui: &mut egui::Ui, title: &str, value: &str, color: egui::Color32) {
    ui.allocate_ui(Vec2::new(190.0, 86.0), |ui| {
        egui::Frame::group(ui.style()).show(ui, |ui| {
            ui.set_min_width(170.0);
            ui.label(theme::section_label(title));
            ui.label(RichText::new(value).size(26.0).strong().color(color));
        });
    });
}

fn status_dot(ui: &mut egui::Ui, tone: StatusTone) {
    let (rect, _) = ui.allocate_exact_size(Vec2::splat(10.0), Sense::hover());
    ui.painter().circle_filled(rect.center(), 4.0, tone_color(tone));
}

fn clickable(ui: &mut egui::Ui, text: impl Into<egui::WidgetText>) -> bool {
    ui.add(egui::Label::new(text).sense(Sense::click())).clicked()
}

fn header_cell(
    header: &mut egui_extras::TableRow<'_, '_>,
    title: &str,
    sort: SortCol,
    asc: bool,
    column: SortCol,
) -> Option<SortCol> {
    let mut clicked = None;
    header.col(|ui| {
        let marker = if sort == column {
            if asc { " ↑" } else { " ↓" }
        } else {
            ""
        };
        if ui.selectable_label(sort == column, format!("{title}{marker}")).clicked() {
            clicked = Some(column);
        }
    });
    clicked
}

fn ready_header(kind: ResourceKind) -> &'static str {
    match kind {
        ResourceKind::Events => "Count",
        ResourceKind::Services => "Cluster IP",
        ResourceKind::Ingresses => "Class",
        ResourceKind::ConfigMaps | ResourceKind::Secrets => "Keys",
        ResourceKind::Nodes => "Kubelet",
        _ => "Ready",
    }
}

fn compare_rows(a: &ResourceRow, b: &ResourceRow, sort: SortCol, asc: bool) -> std::cmp::Ordering {
    let ordering = match sort {
        SortCol::Name => a.name.cmp(&b.name),
        SortCol::Namespace => a.namespace.cmp(&b.namespace).then(a.name.cmp(&b.name)),
        SortCol::Status => a.status.cmp(&b.status).then(a.name.cmp(&b.name)),
        SortCol::Ready => a.ready.cmp(&b.ready).then(a.name.cmp(&b.name)),
        SortCol::Age => a.age_secs.cmp(&b.age_secs).then(a.name.cmp(&b.name)),
        SortCol::Cpu => cmp_opt(a.cpu_millis, b.cpu_millis, asc).then(a.name.cmp(&b.name)),
        SortCol::Memory => cmp_opt(a.mem_bytes, b.mem_bytes, asc).then(a.name.cmp(&b.name)),
        SortCol::Info => a.info.cmp(&b.info).then(a.name.cmp(&b.name)),
    };
    if asc { ordering } else { ordering.reverse() }
}

fn cmp_opt(a: Option<f64>, b: Option<f64>, asc: bool) -> std::cmp::Ordering {
    match (a, b) {
        (Some(a), Some(b)) => a.partial_cmp(&b).unwrap_or(std::cmp::Ordering::Equal),
        (Some(_), None) => {
            if asc {
                std::cmp::Ordering::Less
            } else {
                std::cmp::Ordering::Greater
            }
        }
        (None, Some(_)) => {
            if asc {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Less
            }
        }
        (None, None) => std::cmp::Ordering::Equal,
    }
}

pub fn run() -> eframe::Result<()> {
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_inner_size([1440.0, 900.0])
            .with_min_inner_size([1024.0, 680.0])
            .with_title("Kubi")
            .with_app_id("kubi"),
        renderer: eframe::Renderer::Wgpu,
        ..Default::default()
    };
    eframe::run_native(
        "Kubi",
        options,
        Box::new(|cc| {
            theme::apply(&cc.egui_ctx);
            Ok(Box::new(KubiApp::new()))
        }),
    )
}

