        (false, false) => format!("{class} · {reclaim}"),
        (false, true) => class,
        (true, false) => reclaim,
        (true, true) => String::new(),
    };
    make_row(
        &item.metadata,
        phase.clone(),
        phase_tone(&phase),
        storage,
        info,
        None,
        None,
    )
