fn phase_tone(phase: &str) -> StatusTone {
    match phase {
        "Active" | "Bound" | "Available" | "Ready" | "Running" => StatusTone::Ok,
        "Pending" | "Released" | "Terminating" => StatusTone::Warn,
        "Failed" | "Lost" => StatusTone::Bad,
        _ => StatusTone::Neutral,
