fn cluster_hotbar(&mut self, ui: &mut egui::Ui) {
    let contexts = self.contexts.clone();
    let active = self.context.clone();
    let mut picked = None;
    let mut open_config = false;
    egui::Panel::right("clusters")
        .exact_size(56.0)
        .resizable(false)
        .frame(egui::Frame::side_top_panel(&ui.style()).fill(theme::SIDEBAR))
        .show(ui, |ui| {
            ui.allocate_ui_with_layout(
                Vec2::new(ui.available_width(), ui.available_height()),
                Layout::bottom_up(Align::Center),
                |ui| {
                    ui.add_space(8.0);
                    if ui
                        .add_sized(Vec2::splat(28.0), egui::Button::new("+"))
                        .on_hover_text("Open kubeconfig")
                        .clicked()
                    {
                        open_config = true;
                    }
                    ui.add_space(4.0);
                    ScrollArea::vertical()
                        .id_salt("cluster-hotbar")
                        .show(ui, |ui| {
                            ui.add_space(8.0);
                            ui.vertical_centered(|ui| {
                                for ctx in &contexts {
                                    let is_active = active.as_deref() == Some(ctx.name.as_str());
                                    if cluster_chip(ui, ctx, is_active) {
                                        picked = Some(ctx.name.clone());
                                    }
                                    ui.add_space(6.0);
                                }
                            });
                        });
                },
            );
        });
    if let Some(name) = picked {
        self.switch_context(name);
    }
    if open_config {
        self.open_kubeconfig();
    }
}

