fn spawn_crd_catalog(
    client: Client,
    context: String,
    cancel: CancellationToken,
    events: std::sync::mpsc::Sender<AppEvent>,
) {
    let api = Api::<CustomResourceDefinition>::all(client);
    tokio::spawn(async move {
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        let reader_cancel = cancel.clone();
        tokio::spawn(async move {
            let mut stream = std::pin::pin!(watcher(api, watcher::Config::default()));
            loop {
                tokio::select! {
                    _ = reader_cancel.cancelled() => break,
                    item = stream.next() => {
                        match item {
                            None => break,
                            Some(item) => {
                                if tx.send(item).is_err() {
                                    break;
                                }
                            }
                        }
                    }
                }
            }
        });

        let mut targets = Vec::new();
        let mut dirty = false;
        let mut deadline = tokio::time::Instant::now();
        loop {
            tokio::select! {
                _ = cancel.cancelled() => break,
                _ = tokio::time::sleep_until(deadline), if dirty => {
                    publish_catalog(&events, &context, &targets);
                    dirty = false;
                }
                item = rx.recv() => {
                    let Some(item) = item else { break };
                    match item {
                        Ok(WatchEvent::Init) => targets.clear(),
                        Ok(WatchEvent::InitApply(object)) => {
                            if let Some(target) = crd_target(&object) {
                                upsert_target(&mut targets, target);
                            }
                        }
                        Ok(WatchEvent::InitDone) => {
                            publish_catalog(&events, &context, &targets);
                            dirty = false;
                        }
                        Ok(WatchEvent::Apply(object)) => {
                            if let Some(target) = crd_target(&object) {
                                upsert_target(&mut targets, target);
                                if !dirty {
                                    deadline = tokio::time::Instant::now() + Duration::from_millis(200);
                                    dirty = true;
                                }
                            }
                        }
                        Ok(WatchEvent::Delete(object)) => {
                            if let Some(name) = object.metadata.name {
                                targets.retain(|target| target.name != name);
                                if !dirty {
                                    deadline = tokio::time::Instant::now() + Duration::from_millis(200);
                                    dirty = true;
                                }
                            }
                        }
                        Err(err) => {
                            let _ = events.send(AppEvent::Error(format!("watch CRDs: {err}")));
                        }
                    }
                }
            }
        }
    });
}

fn crd_target(crd: &CustomResourceDefinition) -> Option<CrTarget> {
    let name = crd.metadata.name.clone()?;
    let version = crd
        .spec
        .versions
        .iter()
        .find(|version| version.storage)
        .or_else(|| crd.spec.versions.iter().find(|version| version.served))?;
    Some(CrTarget {
        name,
        kind: crd.spec.names.kind.clone(),
        group: crd.spec.group.clone(),
        version: version.name.clone(),
        plural: crd.spec.names.plural.clone(),
        namespaced: crd.spec.scope != "Cluster",
    })
}

fn upsert_target(targets: &mut Vec<CrTarget>, target: CrTarget) {
    if let Some(slot) = targets.iter_mut().find(|item| item.name == target.name) {
        *slot = target;
    } else {
        targets.push(target);
    }
}

fn publish_catalog(
    events: &std::sync::mpsc::Sender<AppEvent>,
    context: &str,
    targets: &[CrTarget],
) {
    let mut targets = targets.to_vec();
    targets.sort_by(|a, b| a.group.cmp(&b.group).then(a.kind.cmp(&b.kind)));
    let _ = events.send(AppEvent::CustomResources {
        context: context.to_string(),
        targets,
    });
}

