pub const ROW_SELECTED: Color32 = Color32::from_rgb(82, 82, 82);
pub const SEPARATOR: Color32 = Color32::from_rgb(62, 62, 62);

pub fn apply(ctx: &egui::Context) {
    let mut visuals = egui::Visuals::dark();
