fn tab_strip(&mut self, ui: &mut egui::Ui) {
    let mut activate = None;
    let mut close = None;
    let active = self.active;
    let titles: Vec<String> = self.tabs.iter().map(|tab| title_of(&tab.view)).collect();
    egui::Frame::new()
        .fill(theme::TAB_STRIP)
        .inner_margin(egui::Margin::symmetric(4, 0))
        .show(ui, |ui| {
            ScrollArea::horizontal()
                .id_salt("resource-tabs")
                .max_height(32.0)
                .show(ui, |ui| {
                    ui.horizontal(|ui| {
                        ui.spacing_mut().item_spacing.x = 0.0;
                        ui.set_min_height(32.0);
                        for (index, title) in titles.iter().enumerate() {
                            let is_active = active == Some(index);
                            let width = (title.len() as f32).mul_add(7.0, 36.0).max(80.0);
                            let (rect, response) = ui.allocate_exact_size(
                                Vec2::new(width, 32.0),
                                Sense::click(),
                            );
                            if is_active {
                                ui.painter().rect_filled(rect, 0, HOVER);
                                ui.painter().hline(
                                    rect.x_range(),
                                    rect.bottom() - 1.0,
                                    Stroke::new(2.0, ACCENT),
                                );
                            } else if response.hovered() {
                                ui.painter().rect_filled(rect, 0, Color32::from_rgb(54, 54, 54));
                            }
                            ui.painter().text(
                                rect.left_center() + Vec2::new(10.0, 0.0),
                                Align2::LEFT_CENTER,
                                title,
                                FontId::proportional(12.0),
                                if is_active { TEXT } else { MUTED },
                            );
                            let close_rect = egui::Rect::from_center_size(
                                rect.right_center() - Vec2::new(12.0, 0.0),
                                Vec2::splat(16.0),
                            );
                            let close_response = ui.interact(
                                close_rect,
                                ui.id().with(("tab-close", index)),
                                Sense::click(),
                            );
                            ui.painter().text(
                                close_rect.center(),
                                Align2::CENTER_CENTER,
                                "×",
                                FontId::proportional(14.0),
                                MUTED,
                            );
                            if close_response.clicked() {
                                close = Some(index);
                            } else if response.clicked() {
                                activate = Some(index);
                            }
                        }
                    });
                });
        });
    if let Some(index) = close {
        self.close_tab(index);
    } else if let Some(index) = activate {
        self.activate_tab(index);
    }
}

