fn group_header(ui: &mut egui::Ui, label: &str, count: usize, open: bool, indent: f32) -> bool {
    let width = ui.available_width();
    let (full, response) = ui.allocate_exact_size(Vec2::new(width, 22.0), Sense::click());
    let rect = egui::Rect::from_min_max(
        full.min + Vec2::new(6.0 + indent, 1.0),
        full.max - Vec2::new(6.0, 1.0),
    );
    let hovered = ui.rect_contains_pointer(full);
    if hovered {
        ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
        ui.painter()
            .rect_filled(rect, CornerRadius::same(6), HOVER);
    }
    let color = if hovered { MUTED } else { TREE_FAINT };
    let chevron_x = rect.left() + 10.0;
    ui.painter().text(
        egui::pos2(chevron_x, rect.center().y),
        Align2::CENTER_CENTER,
        if open { "▾" } else { "▸" },
        FontId::proportional(10.0),
        color,
    );
    let text = if open {
        label.to_string()
    } else {
        format!("{label}  ·  {count}")
    };
    ui.painter().text(
        egui::pos2(chevron_x + 12.0, rect.center().y),
        Align2::LEFT_CENTER,
        text,
        FontId::proportional(11.0),
        color,
    );
    response
        .on_hover_text(if open {
            "Hide these resources"
        } else {
            "Show these resources"
        })
        .clicked()
}

fn resource_row(ui: &mut egui::Ui, label: &str, selected: bool, indent: f32) -> bool {
    let width = ui.available_width();
    let (full, response) = ui.allocate_exact_size(Vec2::new(width, 28.0), Sense::click());
    let rect = egui::Rect::from_min_max(
        full.min + Vec2::new(6.0 + indent, 3.0),
        full.max - Vec2::new(6.0, 3.0),
    );
    let hovered = ui.rect_contains_pointer(full);
    if hovered {
        ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
    }
    let fill = if selected {
        theme::ROW_SELECTED
    } else if hovered {
        HOVER
    } else {
        Color32::TRANSPARENT
    };
    if fill != Color32::TRANSPARENT {
        ui.painter()
            .rect_filled(rect, CornerRadius::same(6), fill);
    }
    if selected {
        ui.painter().text(
            egui::pos2(rect.left() + 12.0, rect.center().y),
            Align2::CENTER_CENTER,
            "•",
            FontId::proportional(14.0),
            ACCENT,
        );
    }
    let text_color = if selected { TEXT } else { MUTED };
    let label_rect = egui::Rect::from_min_max(
        egui::pos2(rect.left() + 20.0, rect.top()),
        egui::pos2(rect.right() - 8.0, rect.bottom()),
