async fn overview(client: &Client, context: String) -> Result<ClusterOverview, String> {
    let nodes = list_all(Api::<Node>::all(client.clone())).await?;
    let pods = list_all(Api::<Pod>::all(client.clone())).await?;
    let namespaces = list_namespaces(client).await.unwrap_or_default();
    let events = list_all(Api::<Event>::all(client.clone())).await;
    let nodes_total = nodes.len() as u32;
    let nodes_ready = nodes.iter().filter(|node| node_is_ready(node)).count() as u32;
    let phases = pod_phases(&pods);
    let (cpu_alloc, mem_alloc) = node_capacity(&nodes);
    let (cpu_millis, mem_bytes) = node_usage_totals(client).await;
    let (warning_events, warnings, note) = match events {
        Ok(events) => {
            let warnings = recent_warnings(&events);
            let count = warnings_count(&events);
            (Some(count), warnings, None)
        }
        Err(err) => (None, Vec::new(), Some(format!("Events unavailable: {err}"))),
    };
    let argo = argo_overview(client).await;
    Ok(ClusterOverview {
        context,
        nodes_ready,
        nodes_total,
        pods: pods.len() as u32,
        pods_running: phases.0,
        pods_pending: phases.1,
        pods_failed: phases.2,
        pods_succeeded: phases.3,
        pods_unknown: phases.4,
        namespaces: namespaces.len() as u32,
        warning_events,
        warnings,
        cpu_millis,
        cpu_allocatable_millis: cpu_millis.and(cpu_alloc),
        mem_bytes,
        mem_allocatable_bytes: mem_bytes.and(mem_alloc),
        note,
        argo,
    })
}

fn pod_phases(pods: &[Pod]) -> (u32, u32, u32, u32, u32) {
    let mut running = 0;
    let mut pending = 0;
    let mut failed = 0;
    let mut succeeded = 0;
    let mut unknown = 0;
    for pod in pods {
        match pod.status.as_ref().and_then(|status| status.phase.as_deref()) {
            Some("Running") => running += 1,
            Some("Pending") => pending += 1,
            Some("Failed") => failed += 1,
            Some("Succeeded") => succeeded += 1,
            _ => unknown += 1,
        }
    }
    (running, pending, failed, succeeded, unknown)
}

fn node_capacity(nodes: &[Node]) -> (Option<f64>, Option<f64>) {
    let mut cpu = 0.0;
    let mut mem = 0.0;
    let mut any_cpu = false;
    let mut any_mem = false;
    for node in nodes {
        let Some(allocatable) = node.status.as_ref().and_then(|status| status.allocatable.as_ref())
        else {
            continue;
        };
        if let Some(value) = allocatable.get("cpu").and_then(|qty| parse_cpu_millis(&qty.0)) {
            cpu += value;
            any_cpu = true;
        }
        if let Some(value) = allocatable.get("memory").and_then(|qty| parse_bytes(&qty.0)) {
            mem += value;
            any_mem = true;
        }
    }
    (any_cpu.then_some(cpu), any_mem.then_some(mem))
}

async fn node_usage_totals(client: &Client) -> (Option<f64>, Option<f64>) {
    let Ok(metrics) = list_all(Api::<NodeMetrics>::all(client.clone())).await else {
        return (None, None);
    };
    if metrics.is_empty() {
        return (None, None);
    }
    let mut cpu = 0.0;
    let mut mem = 0.0;
    for sample in metrics.iter().filter_map(node_usage) {
        cpu += sample.cpu_millis;
        mem += sample.mem_bytes;
    }
    (Some(cpu), Some(mem))
}

fn warnings_count(events: &[Event]) -> u32 {
    events
        .iter()
        .filter(|event| event.type_.as_deref() == Some("Warning"))
        .count() as u32
}

fn recent_warnings(events: &[Event]) -> Vec<OverviewWarning> {
    let mut warnings: Vec<OverviewWarning> = events
        .iter()
        .filter(|event| event.type_.as_deref() == Some("Warning"))
        .map(|event| {
            let kind = event.involved_object.kind.as_deref().unwrap_or("Object");
            let name = event
                .involved_object
                .name
                .clone()
                .unwrap_or_else(|| "-".to_string());
            let age_secs = event
                .last_timestamp
                .as_ref()
                .or(event.metadata.creation_timestamp.as_ref())
                .map(event_age)
                .unwrap_or(u64::MAX);
            OverviewWarning {
                object: format!("{kind}/{name}"),
                reason: event.reason.clone().unwrap_or_else(|| "Warning".to_string()),
                message: truncate_chars(event.message.as_deref().unwrap_or(""), 160),
                age_secs,
            }
        })
        .collect();
    warnings.sort_by_key(|warning| warning.age_secs);
    warnings.truncate(8);
    warnings
}

fn event_age(ts: &k8s_openapi::apimachinery::pkg::apis::meta::v1::Time) -> u64 {
    let then = ts.0.as_second();
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_secs() as i64)
        .unwrap_or(0);
    now.saturating_sub(then).max(0) as u64
}

fn truncate_chars(text: &str, max_chars: usize) -> String {
    let count = text.chars().count();
    if count <= max_chars {
        text.to_string()
    } else {
        let trimmed: String = text.chars().take(max_chars).collect();
        format!("{trimmed}…")
    }
}

async fn argo_overview(client: &Client) -> Option<ArgoOverview> {
    let discovery = Discovery::new(client.clone())
        .filter(&["argoproj.io"])
        .run()
        .await
        .ok()?;
    let mut chosen: Option<(kube::api::ApiResource, kube::discovery::Scope)> = None;
    let mut target = None;
    for group in discovery.groups() {
        for (resource, caps) in group.resources_by_stability() {
            if resource.kind != "Application"
                || !caps.supports_operation(kube::discovery::verbs::LIST)
            {
                continue;
            }
            let name = format!("{}.{}", resource.plural, resource.group);
            target = Some(CrTarget {
                name,
                kind: resource.kind.clone(),
                group: resource.group.clone(),
                version: resource.version.clone(),
                plural: resource.plural.clone(),
                namespaced: caps.scope == Scope::Namespaced,
            });
            chosen = Some((resource, caps.scope));
            if target.as_ref().is_some_and(|item| item.version == "v1alpha1") {
                break;
            }
        }
    }
    let (resource, scope) = chosen?;
    let target = target?;
    let api = if scope == Scope::Namespaced {
        Api::<DynamicObject>::all_with(client.clone(), &resource)
    } else {
        Api::<DynamicObject>::all_with(client.clone(), &resource)
    };
    match list_all(api).await {
        Ok(items) => {
            let mut apps: Vec<ArgoApp> = items.iter().filter_map(argo_app).collect();
            apps.sort_by(|a, b| a.name.cmp(&b.name));
            Some(ArgoOverview {
                target,
                apps,
                note: None,
            })
        }
        Err(err) => Some(ArgoOverview {
            target,
            apps: Vec::new(),
            note: Some(err),
        }),
    }
}

fn argo_app(object: &DynamicObject) -> Option<ArgoApp> {
    let name = object.metadata.name.clone()?;
    let namespace = object.metadata.namespace.clone().unwrap_or_default();
    let project = object
        .data
        .get("spec")
        .and_then(|spec| spec.get("project"))
        .and_then(|value| value.as_str())
        .unwrap_or("-")
        .to_string();
    let health = json_status(&object.data, "health").unwrap_or_else(|| "Unknown".to_string());
    let sync = json_status(&object.data, "sync").unwrap_or_else(|| "Unknown".to_string());
    Some(ArgoApp {
        name,
        namespace,
        project,
        health,
        sync,
    })
}

