fn argo_section(ui: &mut egui::Ui, argo: &ArgoOverview) -> Option<ArgoApp> {
    ui.label(RichText::new("Argo CD").size(13.0).color(TEXT));
    ui.add_space(6.0);
    if let Some(note) = &argo.note {
        ui.label(RichText::new(note).size(12.0).color(BAD));
    }
    let mut health = [0u32; 5];
    let mut sync = [0u32; 3];
    for app in &argo.apps {
        match app.health.as_str() {
            "Healthy" => health[0] += 1,
            "Degraded" => health[1] += 1,
            "Progressing" => health[2] += 1,
            "Missing" => health[3] += 1,
            _ => health[4] += 1,
        }
        match app.sync.as_str() {
            "Synced" => sync[0] += 1,
            "OutOfSync" => sync[1] += 1,
            _ => sync[2] += 1,
        }
    }
    share_bar(
        ui,
        "Health",
        &[
            ("Healthy", health[0], OK),
            ("Degraded", health[1], BAD),
            ("Progressing", health[2], WARN),
            ("Missing", health[3], BAD),
            ("Unknown", health[4], MUTED),
        ],
    );
    ui.add_space(8.0);
    share_bar(
        ui,
        "Sync",
        &[
            ("Synced", sync[0], OK),
            ("OutOfSync", sync[1], WARN),
            ("Unknown", sync[2], MUTED),
        ],
    );
    ui.add_space(8.0);
    let mut picked = None;
    for app in &argo.apps {
        let (rect, response) = ui.allocate_exact_size(Vec2::new(ui.available_width().min(640.0), 28.0), Sense::click());
        if response.hovered() {
            ui.painter().rect_filled(rect, CornerRadius::same(3), HOVER);
            ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
        }
        let place = if app.namespace.is_empty() {
            app.name.clone()
        } else {
            format!("{}/{}", app.namespace, app.name)
        };
        ui.painter().text(
            rect.left_center() + Vec2::new(8.0, 0.0),
            Align2::LEFT_CENTER,
            format!(
                "{place}   {}   {}   {}",
                app.project,
                app.health,
                app.sync
            ),
            FontId::proportional(12.0),
            if app.health == "Healthy" { TEXT } else { MUTED },
        );
        if response.clicked() {
            picked = Some(app.clone());
        }
    }
    picked
}

