    if entries.is_empty() {
        ui.label(RichText::new("No keys.").color(MUTED));
        return;
    }
    ScrollArea::vertical()
        .id_salt("object-data")
        .auto_shrink([false, false])
        .show(ui, |ui| {
            for entry in entries {
                ui.add_space(6.0);
