fn argo_counts(argo: &ArgoOverview) -> ([u32; 5], [u32; 3]) {
    let mut health = [0u32; 5];
    let mut sync = [0u32; 3];
    for app in &argo.apps {
        match app.health.as_str() {
            "Healthy" => health[0] += 1,
            "Degraded" => health[1] += 1,
            "Progressing" => health[2] += 1,
            "Missing" => health[3] += 1,
            _ => health[4] += 1,
        }
        match app.sync.as_str() {
            "Synced" => sync[0] += 1,
            "OutOfSync" => sync[1] += 1,
            _ => sync[2] += 1,
        }
    }
    (health, sync)
}

fn progress_ring(ui: &mut egui::Ui, value: u32, total: u32, color: Color32) {
    let size = 96.0;
    let (rect, _) = ui.allocate_exact_size(Vec2::splat(size), Sense::hover());
    let center = rect.center();
    let radius = 34.0;
    let stroke = 6.0;
    paint_arc(
        ui.painter(),
        center,
        radius,
        -std::f32::consts::FRAC_PI_2,
        std::f32::consts::TAU,
        Stroke::new(stroke, SEPARATOR),
    );
    let ratio = if total == 0 {
        0.0
    } else {
        value as f32 / total as f32
    };
    if ratio > 0.0 {
        paint_arc(
            ui.painter(),
            center,
            radius,
            -std::f32::consts::FRAC_PI_2,
            ratio * std::f32::consts::TAU,
            Stroke::new(stroke, color),
        );
    }
    ui.painter().text(
        center,
        Align2::CENTER_CENTER,
        format!("{value}/{total}"),
        FontId::proportional(12.0),
        TEXT,
    );
}

fn paint_arc(
    painter: &egui::Painter,
    center: egui::Pos2,
    radius: f32,
    start: f32,
    sweep: f32,
    stroke: Stroke,
) {
    if sweep.abs() < 0.01 {
        return;
    }
    let steps = ((sweep.abs() / std::f32::consts::TAU) * 72.0)
        .ceil()
        .max(2.0) as usize;
    let mut points = Vec::with_capacity(steps + 1);
    for step in 0..=steps {
        let angle = start + sweep * (step as f32 / steps as f32);
        points.push(center + Vec2::new(angle.cos(), angle.sin()) * radius);
    }
    painter.add(egui::Shape::line(points, stroke));
}

fn status_legend(ui: &mut egui::Ui, parts: &[(&str, u32, Color32)]) {
    let shown: Vec<_> = parts.iter().filter(|part| part.1 > 0).collect();
    if shown.is_empty() {
        return;
    }
    ui.add_space(8.0);
    ui.horizontal_wrapped(|ui| {
        for (name, value, color) in shown {
            ui.label(
                RichText::new(format!("{name} {value}"))
                    .size(12.0)
                    .color(*color),
            );
        }
    });
}

