  return kind === "deployments" || kind === "statefulSets" || kind === "daemonSets";
}

export function installedGateway(targets: CrTarget[]): ResourceKind[] {
  const kinds = NAV.find(([title]) => title === "Gateway")?.[1] ?? [];
  return kinds.filter((kind) => {
    const plural = GATEWAY_PLURAL[kind];
    return (
      plural != null &&
      targets.some((target) => target.group === "gateway.networking.k8s.io" && target.plural === plural)
    );
  });
}

export function crGroups(targets: CrTarget[]): [string, CrTarget[]][] {
  const groups = new Map<string, CrTarget[]>();
  for (const target of targets) {
    if (target.group === "gateway.networking.k8s.io") continue;
    const list = groups.get(target.group) ?? [];
    list.push(target);
    groups.set(target.group, list);
  }
  for (const list of groups.values()) {
    list.sort((a, b) => a.kind.localeCompare(b.kind) || a.version.localeCompare(b.version));
  }
  return [...groups.entries()].sort(([a], [b]) => a.localeCompare(b));
}

export function argoInstalled(targets: CrTarget[]): boolean {
  return targets.some((target) => target.group === "argoproj.io" && target.kind === "Application");
}

export function viewTitle(view: View): string {
  if (view.kind === "overview") return "Overview";
  if (view.kind === "argo") return "Argo CD";
  if (view.kind === "resource") return TITLES[view.resource];
  return view.target.kind;
}

export type SearchHit = { view: View; label: string; hint: string };

export function searchHits(query: string, targets: CrTarget[]): SearchHit[] {
  const needle = query.trim().toLowerCase();
  const hits: SearchHit[] = [];
  const contains = (haystack: string) => haystack.toLowerCase().includes(needle);
  if (needle === "" || "overview".includes(needle)) {
    hits.push({ view: { kind: "overview" }, label: "Overview", hint: "" });
  }
  if (argoInstalled(targets) && (needle === "" || "argo cd".includes(needle) || "argocd".includes(needle))) {
    hits.push({ view: { kind: "argo" }, label: "Argo CD", hint: "" });
  }
  for (const [title, kinds] of NAV) {
    const shown = title === "Gateway" ? installedGateway(targets) : kinds;
    for (const kind of shown) {
      if (needle === "" || contains(TITLES[kind]) || contains(title)) {
        hits.push({ view: { kind: "resource", resource: kind }, label: TITLES[kind], hint: title });
      }
    }
  }
  if (needle === "" || "definitions".includes(needle) || "customresourcedefinitions".includes(needle)) {
    hits.push({
      view: { kind: "resource", resource: "customResourceDefinitions" },
      label: "Definitions",
      hint: "Custom Resources",
    });
  }
  for (const target of targets) {
    if (needle === "" || contains(target.kind) || contains(target.group)) {
      hits.push({
        view: { kind: "custom", target },
        label: target.kind,
        hint: target.group,
      });
    }
  }
  return hits;
}

import type { ResourceKind, ResourceRow, View } from "./types";
import { isNamespaced } from "./catalog";
import { formatAge, formatBytesPair, formatCpuPair } from "./format";

export type Field =
  | "name"
  | "namespace"
  | "age"
  | "status"
  | "ready"
  | "info"
  | "cpu"
  | "memory"
  | { cell: string };

export type Col = {
  title: string;
  field: Field;
  colored: boolean;
  width: number;
};

function col(title: string, field: Field, colored: boolean, width: number): Col {
  return { title, field, colored, width };
}

function keyOf(field: Field): string {
  return typeof field === "string" ? field : `cell:${field.cell}`;
}

export function columnKey(field: Field): string {
  return keyOf(field);
}

export function columnsFor(view: View): Col[] {
  const cols: Col[] = [col("Name", "name", false, 220)];
  const namespaced = view.kind === "custom" ? view.target.namespaced : view.kind === "resource" ? isNamespaced(view.resource) : false;
  if (namespaced) cols.push(col("Namespace", "namespace", false, 140));
  const kind: ResourceKind | null = view.kind === "resource" ? view.resource : null;
  const middle = middleColumns(kind);
  for (const [title, field, colored] of middle) {
    const width = field === "cpu" || field === "memory" ? 110 : 140;
    cols.push(col(title, field, colored, width));
  }
  cols.push(col("Age", "age", false, 72));
  return cols;
}

function middleColumns(kind: ResourceKind | null): [string, Field, boolean][] {
  switch (kind) {
    case "pods":
      return [
        ["Status", "status", true],
        ["Ready", "ready", false],
        ["Restarts", { cell: "restarts" }, false],
        ["Node", { cell: "node" }, false],
        ["CPU", "cpu", false],
        ["Memory", "memory", false],
      ];
    case "nodes":
      return [
        ["Status", "status", true],
        ["Roles", "info", false],
        ["Kubelet", "ready", false],
        ["CPU", "cpu", false],
        ["Memory", "memory", false],
      ];
    case "deployments":
    case "replicaSets":
    case "statefulSets":
    case "daemonSets":
      return [
        ["Status", "status", true],
        ["Ready", "ready", false],
      ];
    case "jobs":
      return [
        ["Status", "status", true],
        ["Completions", "ready", false],
      ];
    case "cronJobs":
      return [
        ["Schedule", "info", false],
        ["Suspend", "status", true],
        ["Active", "ready", false],
      ];
    case "services":
      return [
        ["Type", "status", false],
        ["Cluster IP", "ready", false],
        ["Ports", "info", false],
      ];
    case "endpoints":
      return [
        ["Status", "status", true],
        ["Addresses", "ready", false],
        ["Not ready", "info", false],
      ];
    case "endpointSlices":
      return [
        ["Address type", "status", false],
        ["Endpoints", "ready", false],
      ];
    case "ingresses":
      return [
        ["Class", "ready", false],
        ["Hosts", "info", false],
      ];
    case "ingressClasses":
      return [["Controller", "ready", false]];
    case "gatewayClasses":
      return [["Controller", { cell: "controller" }, false]];
    case "networkPolicies":
      return [
        ["Types", "ready", false],
        ["Rules", "info", false],
      ];
    case "configMaps":
      return [
        ["Keys", "ready", false],
        ["Data", "info", false],
      ];
    case "secrets":
      return [
        ["Keys", "ready", false],
        ["Type", "status", false],
      ];
    case "resourceQuotas":
      return [
        ["Used", "ready", false],
        ["Hard", "info", false],
      ];
    case "limitRanges":
      return [
        ["Limits", "ready", false],
        ["Types", "info", false],
      ];
    case "horizontalPodAutoscalers":
      return [
        ["Replicas", "ready", false],
        ["Target", "info", false],
      ];
    case "podDisruptionBudgets":
      return [
        ["Healthy", "ready", false],
        ["Budget", "info", false],
      ];
    case "persistentVolumeClaims":
    case "persistentVolumes":
      return [
        ["Phase", "status", true],
        ["Size", "ready", false],
        ["Class", { cell: "class" }, false],
      ];
    case "storageClasses":
      return [
        ["Provisioner", "info", false],
        ["Reclaim", "ready", false],
      ];
    case "serviceAccounts":
      return [
        ["Secrets", "ready", false],
        ["Pull secrets", "info", false],
      ];
    case "roles":
    case "clusterRoles":
      return [["Rules", "ready", false]];
    case "roleBindings":
    case "clusterRoleBindings":
      return [
        ["Subjects", "ready", false],
        ["Role", "info", false],
      ];
    case "namespaces":
      return [["Phase", "status", true]];
    case "events":
      return [
        ["Reason", { cell: "reason" }, true],
        ["Object", { cell: "object" }, false],
        ["Count", { cell: "count" }, false],
        ["Message", { cell: "message" }, false],
      ];
    case "customResourceDefinitions":
      return [
        ["Established", "status", true],
        ["Scope", "ready", false],
        ["Group", "info", false],
      ];
    case "gateways":
      return [
        ["Class", { cell: "class" }, false],
        ["Listeners", { cell: "listeners" }, false],
        ["Addresses", { cell: "addresses" }, false],
      ];
    case "httpRoutes":
    case "grpcRoutes":
    case "tlsRoutes":
      return [
        ["Hostnames", { cell: "hostnames" }, false],
        ["Parent", { cell: "parent" }, false],
      ];
    case "tcpRoutes":
    case "udpRoutes":
      return [
        ["Parent", { cell: "parent" }, false],
        ["Backends", { cell: "backends" }, false],
      ];
    case "backendTLSPolicies":
      return [
        ["Target", { cell: "target" }, false],
        ["Hostname", { cell: "hostname" }, false],
      ];
    case "referenceGrants":
      return [
        ["From", { cell: "from" }, false],
        ["To", { cell: "to" }, false],
      ];
    case "listenerSets":
      return [
        ["Gateway", { cell: "gateway" }, false],
        ["Listeners", { cell: "listeners" }, false],
      ];
    default:
      return [["Status", "status", true]];
  }
}

export function fieldText(row: ResourceRow, field: Field): string {
  let text = "";
  if (field === "name") text = row.name;
  else if (field === "namespace") text = row.namespace;
  else if (field === "age") text = formatAge(row.ageSecs);
  else if (field === "status") text = row.status;
  else if (field === "ready") text = row.ready;
  else if (field === "info") text = row.info;
  else if (field === "cpu") text = formatCpuPair(row.cpuMillis, row.cpuRequestMillis);
  else if (field === "memory") text = formatBytesPair(row.memBytes, row.memRequestBytes);
  else text = row.cells[field.cell] ?? "";
  return text === "" ? "-" : text;
}

export function compareRows(a: ResourceRow, b: ResourceRow, field: Field, asc: boolean): number {
  const left = field === "age" ? a.ageSecs : fieldText(a, field);
  const right = field === "age" ? b.ageSecs : fieldText(b, field);
  const order = left < right ? -1 : left > right ? 1 : 0;
  return asc ? order : -order;
}

import type { CrTarget, ResourceKind, View } from "./types";
import { isNamespaced } from "./catalog";

const MANIFEST: Record<ResourceKind, [string, string]> = {
  nodes: ["v1", "Node"],
  namespaces: ["v1", "Namespace"],
  events: ["v1", "Event"],
  pods: ["v1", "Pod"],
  deployments: ["apps/v1", "Deployment"],
  replicaSets: ["apps/v1", "ReplicaSet"],
  statefulSets: ["apps/v1", "StatefulSet"],
  daemonSets: ["apps/v1", "DaemonSet"],
  jobs: ["batch/v1", "Job"],
  cronJobs: ["batch/v1", "CronJob"],
  services: ["v1", "Service"],
  endpoints: ["v1", "Endpoints"],
  endpointSlices: ["discovery.k8s.io/v1", "EndpointSlice"],
  ingresses: ["networking.k8s.io/v1", "Ingress"],
  ingressClasses: ["networking.k8s.io/v1", "IngressClass"],
  networkPolicies: ["networking.k8s.io/v1", "NetworkPolicy"],
  configMaps: ["v1", "ConfigMap"],
  secrets: ["v1", "Secret"],
  resourceQuotas: ["v1", "ResourceQuota"],
  limitRanges: ["v1", "LimitRange"],
  horizontalPodAutoscalers: ["autoscaling/v2", "HorizontalPodAutoscaler"],
  podDisruptionBudgets: ["policy/v1", "PodDisruptionBudget"],
  persistentVolumeClaims: ["v1", "PersistentVolumeClaim"],
  persistentVolumes: ["v1", "PersistentVolume"],
  storageClasses: ["storage.k8s.io/v1", "StorageClass"],
  serviceAccounts: ["v1", "ServiceAccount"],
  roles: ["rbac.authorization.k8s.io/v1", "Role"],
  roleBindings: ["rbac.authorization.k8s.io/v1", "RoleBinding"],
  clusterRoles: ["rbac.authorization.k8s.io/v1", "ClusterRole"],
  clusterRoleBindings: ["rbac.authorization.k8s.io/v1", "ClusterRoleBinding"],
  gatewayClasses: ["gateway.networking.k8s.io/v1", "GatewayClass"],
  gateways: ["gateway.networking.k8s.io/v1", "Gateway"],
  httpRoutes: ["gateway.networking.k8s.io/v1", "HTTPRoute"],
  grpcRoutes: ["gateway.networking.k8s.io/v1", "GRPCRoute"],
  referenceGrants: ["gateway.networking.k8s.io/v1beta1", "ReferenceGrant"],
  tlsRoutes: ["gateway.networking.k8s.io/v1", "TLSRoute"],
  tcpRoutes: ["gateway.networking.k8s.io/v1", "TCPRoute"],
  udpRoutes: ["gateway.networking.k8s.io/v1", "UDPRoute"],
  backendTLSPolicies: ["gateway.networking.k8s.io/v1", "BackendTLSPolicy"],
  listenerSets: ["gateway.networking.k8s.io/v1", "ListenerSet"],
  customResourceDefinitions: ["apiextensions.k8s.io/v1", "CustomResourceDefinition"],
};

function kindBody(kind: ResourceKind): string {
  switch (kind) {
    case "configMaps":
      return "data: {}\n";
    case "secrets":
      return "type: Opaque\nstringData: {}\n";
    case "pods":
      return "spec:\n  containers:\n    - name: app\n      image: nginx:1.27\n";
    case "deployments":
      return "spec:\n  replicas: 1\n  selector:\n    matchLabels:\n      app: example\n  template:\n    metadata:\n      labels:\n        app: example\n    spec:\n      containers:\n        - name: app\n          image: nginx:1.27\n";
    case "services":
      return "spec:\n  selector:\n    app: example\n  ports:\n    - port: 80\n      targetPort: 80\n";
    default:
      return "";
  }
}

export function objectTemplate(view: View, namespace: string | null): string {
  const ns = namespace ?? "default";
  if (view.kind === "overview" || view.kind === "argo") return "";
  if (view.kind === "custom") return customTemplate(view.target, ns);
  const [api, name] = MANIFEST[view.resource];
  const namespaceLine = isNamespaced(view.resource) ? `  namespace: ${ns}\n` : "";
  return `apiVersion: ${api}\nkind: ${name}\nmetadata:\n  name: example\n${namespaceLine}${kindBody(view.resource)}`;
}

function customTemplate(target: CrTarget, namespace: string): string {
  const api = target.group === "" ? target.version : `${target.group}/${target.version}`;
  const namespaceLine = target.namespaced ? `  namespace: ${namespace}\n` : "";
  return `apiVersion: ${api}\nkind: ${target.kind}\nmetadata:\n  name: example\n${namespaceLine}`;
}

import { useEffect, useRef, useState } from "react";
import { listen } from "@tauri-apps/api/event";
import { open } from "@tauri-apps/plugin-dialog";
import { send } from "./api";
import type {
  AppEvent,
  ArgoApp,
  ClusterOverview,
  ContextInfo,
  CrTarget,
  DataEntry,
  Home,
  PendingDelete,
  PendingSelect,
  ResourceKind,
  ResourceRow,
  Tab,
  View,
  WatchTarget,
} from "./types";
import { eventKey, sameTarget, sameView, watchOf } from "./types";
import { canRestart, viewTitle } from "./catalog";

type HistPoint = { t: number; cpu: number; mem: number };

type Session = {
  context: string | null;
  active: number | null;
  tabs: Tab[];
  home: Home;
  pending: PendingSelect | null;
  usage: Record<string, [number, number]>;
  defaultNamespace: string | null;
  lastNamespace: string | null;
  nextId: number;
  started: number;
};

function blankTab(view: View, namespace: string | null, id: number): Tab {
  return {
    id,
    view,
    rows: [],
    selected: null,
    detailTab: "overview",
    yaml: null,
    yamlFor: null,
    reveal: false,
    waiting: true,
    filter: "",
    sortKey: "name",
    sortAsc: true,
    namespace,
    data: null,
    dataFor: null,
  };
}

function applyUsage(rows: ResourceRow[], usage: Record<string, [number, number]>): ResourceRow[] {
  return rows.map((row) => {
    const sample = usage[`${row.namespace}/${row.name}`];
    if (!sample) return row;
    return { ...row, cpuMillis: sample[0], memBytes: sample[1] };
  });
}

export function useKubi() {
  const session = useRef<Session>({
    context: null,
    active: null,
    tabs: [],
    home: "cluster",
    pending: null,
    usage: {},
    defaultNamespace: null,
    lastNamespace: null,
    nextId: 1,
    started: performance.now(),
  });
  const [contexts, setContexts] = useState<ContextInfo[]>([]);
  const [context, setContext] = useState<string | null>(null);
  const [namespaces, setNamespaces] = useState<string[]>([]);
  const [tabs, setTabs] = useState<Tab[]>([]);
  const [active, setActive] = useState<number | null>(null);
  const [home, setHome] = useState<Home>("cluster");
  const [customResources, setCustomResources] = useState<CrTarget[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loadingConfig, setLoadingConfig] = useState(true);
  const [connecting, setConnecting] = useState(false);
  const [overview, setOverview] = useState<ClusterOverview | null>(null);
  const [metricsNote, setMetricsNote] = useState<string | null>(null);
  const [history, setHistory] = useState<HistPoint[]>([]);
  const [searchOpen, setSearchOpen] = useState(false);
  const [createOpen, setCreateOpen] = useState(false);
  const [createYaml, setCreateYaml] = useState("");
  const [createError, setCreateError] = useState<string | null>(null);
  const [createBusy, setCreateBusy] = useState(false);
  const [pendingDelete, setPendingDelete] = useState<PendingDelete | null>(null);

  function commitTabs(next: Tab[]) {
    session.current.tabs = next;
    setTabs(next);
  }

  function updateTabs(fn: (tabs: Tab[]) => Tab[]) {
    commitTabs(fn(session.current.tabs));
  }

  function inherited(): string | null {
    const current = session.current;
    if (current.active != null) return current.tabs[current.active]?.namespace ?? null;
    if (current.tabs.length === 0) return current.defaultNamespace;
    return current.lastNamespace;
  }

  function requestYaml(index = session.current.active) {
    if (index == null) return;
    const tab = session.current.tabs[index];
    const target = tab ? watchOf(tab.view) : null;
    const row = tab?.rows.find((item) => item.uid === tab.selected);
    if (!tab || !target || !row) return;
    void send({
      fetchYaml: {
        target,
        namespace: row.namespace,
        name: row.name,
        uid: row.uid,
        revealSecrets: tab.reveal,
      },
    });
  }

  function activate(index: number) {
    const tab = session.current.tabs[index];
    if (!tab) return;
    session.current.active = index;
    setActive(index);
    const target = watchOf(tab.view);
    if (!target) return;
    updateTabs((items) => items.map((item, i) => (i === index ? { ...item, waiting: true } : item)));
    void send({ setNamespace: { namespace: tab.namespace } });
    void send({ watch: { target } });
  }

  function showHome(next: Home) {
    if (session.current.active == null && session.current.home === next) return;
    session.current.home = next;
    session.current.active = null;
    setHome(next);
    setActive(null);
    void send("stopWatch");
    void send("fetchOverview");
  }

  function openView(view: View) {
    if (view.kind === "overview") {
      showHome("cluster");
      return;
    }
    if (view.kind === "argo") {
      showHome("argo");
      return;
    }
    const existing = session.current.tabs.findIndex((tab) => sameView(tab.view, view));
    if (existing >= 0) {
      if (session.current.active === existing) return;
      activate(existing);
      return;
    }
    const tab = blankTab(view, inherited(), session.current.nextId);
    session.current.nextId += 1;
    commitTabs([...session.current.tabs, tab]);
    activate(session.current.tabs.length - 1);
  }

  function selectPending() {
    const pending = session.current.pending;
    if (!pending) return;
    const index = session.current.tabs.findIndex((tab) => {
      const target = watchOf(tab.view);
      return target != null && sameTarget(target, pending.target);
    });
    if (index < 0) return;
    const row = session.current.tabs[index]?.rows.find(
      (item) => item.name === pending.name && item.namespace === pending.namespace,
    );
    if (!row) return;
    session.current.pending = null;
    if (session.current.active !== index) activate(index);
    selectUid(row.uid, index);
  }

  function selectUid(uid: string, index = session.current.active) {
    if (index == null) return;
    const tab = session.current.tabs[index];
    if (!tab || tab.selected === uid) return;
    updateTabs((items) =>
      items.map((item, i) =>
        i === index
          ? { ...item, selected: uid, yaml: null, yamlFor: null, data: null, dataFor: null, detailTab: "overview" }
          : item,
      ),
    );
    setHistory([]);
    requestYaml(index);
  }

  function switchContext(name: string) {
    if (session.current.context === name) return;
    session.current.context = name;
    session.current.defaultNamespace = null;
    session.current.lastNamespace = null;
    session.current.tabs = [];
    session.current.active = null;
    session.current.home = "cluster";
    session.current.pending = null;
    session.current.usage = {};
    setContext(name);
    setNamespaces([]);
    setCustomResources([]);
    setTabs([]);
    setActive(null);
    setHome("cluster");
    setPendingDelete(null);
    setCreateOpen(false);
    setCreateError(null);
    setCreateBusy(false);
    setSearchOpen(false);
    setOverview(null);
    setHistory([]);
    setMetricsNote(null);
    setConnecting(true);
    void send({ connect: { context: name } });
  }

  function pushHistory(namespace: string, name: string, cpu: number, mem: number) {
    const index = session.current.active;
    const tab = index == null ? undefined : session.current.tabs[index];
    const row = tab?.rows.find((item) => item.uid === tab.selected);
    if (!row || row.namespace !== namespace || row.name !== name) return;
    const point = { t: (performance.now() - session.current.started) / 1000, cpu, mem };
    setHistory((points) => {
      const next = [...points];
      const last = next[next.length - 1];
      if (last && point.t - last.t < 1) next[next.length - 1] = point;
      else next.push(point);
      return next.slice(-60);
    });
  }

  const handleRef = useRef<(event: AppEvent) => void>(() => {});
  handleRef.current = (event) => {
    const key = eventKey(event);
    if (key === "contexts" && "contexts" in event) {
      setLoadingConfig(false);
      setError(null);
      setContexts(event.contexts);
      if (event.contexts.length === 0) {
        setConnecting(false);
        setCustomResources([]);
        return;
      }
      const current = session.current.context;
      const pick =
        (current && event.contexts.some((item) => item.name === current) ? current : null) ??
        event.contexts.find((item) => item.current)?.name ??
        event.contexts[0]?.name;
      if (pick) {
        session.current.context = null;
        switchContext(pick);
      }
      return;
    }
    if (key === "connected" && "connected" in event) {
      if (session.current.context !== event.connected.context) return;
      setNamespaces(event.connected.namespaces);
      session.current.defaultNamespace = event.connected.defaultNamespace;
      setConnecting(false);
      setError(null);
      void send("fetchOverview");
      return;
    }
    if (key === "error" && "error" in event) {
      setError(event.error);
      setConnecting(false);
      setLoadingConfig(false);
      return;
    }
    if (key === "customResources" && "customResources" in event) {
      if (session.current.context !== event.customResources.context) return;
      setCustomResources(event.customResources.targets);
      return;
    }
    if (key === "rows" && "rows" in event) {
      const { target, rows } = event.rows;
      const withUsage = applyUsage(rows, session.current.usage);
      updateTabs((items) =>
        items.map((tab) => {
          const watching = watchOf(tab.view);
          if (!watching || !sameTarget(watching, target)) return tab;
          return { ...tab, rows: withUsage, waiting: false };
        }),
      );
      selectPending();
      return;
    }
    if (key === "usage" && "usage" in event) {
      for (const sample of event.usage.samples) {
        session.current.usage[`${sample.namespace}/${sample.name}`] = [sample.cpuMillis, sample.memBytes];
      }
      const index = session.current.active;
      const tab = index == null ? undefined : session.current.tabs[index];
      if (tab?.view.kind === "resource" && tab.view.resource === event.usage.kind) {
        updateTabs((items) =>
          items.map((item, i) => (i === index ? { ...item, rows: applyUsage(item.rows, session.current.usage) } : item)),
        );
        const selected = session.current.tabs[index ?? -1]?.rows.find((row) => row.uid === tab.selected);
        const sample = event.usage.samples.find(
          (item) => item.namespace === selected?.namespace && item.name === selected?.name,
        );
        if (sample) pushHistory(sample.namespace, sample.name, sample.cpuMillis, sample.memBytes);
      }
      return;
    }
    if (key === "metricsUnavailable" && "metricsUnavailable" in event) {
      const index = session.current.active;
      const tab = index == null ? undefined : session.current.tabs[index];
      if (tab?.view.kind === "resource" && tab.view.resource === event.metricsUnavailable.kind) {
        setMetricsNote(event.metricsUnavailable.message);
      }
      return;
    }
    if (key === "yaml" && "yaml" in event) {
      updateTabs((items) =>
        items.map((tab) =>
          tab.selected === event.yaml.uid ? { ...tab, yaml: event.yaml.yaml, yamlFor: event.yaml.uid } : tab,
        ),
      );
      return;
    }
    if (key === "objectData" && "objectData" in event) {
      updateTabs((items) =>
        items.map((tab) =>
          tab.selected === event.objectData.uid
            ? { ...tab, data: event.objectData.entries, dataFor: event.objectData.uid }
            : tab,
        ),
      );
      return;
    }
    if (key === "applyResult" && "applyResult" in event) {
      setCreateBusy(false);
      if (event.applyResult.error) {
        setCreateError(event.applyResult.error);
      } else {
        setCreateOpen(false);
        setCreateError(null);
        const index = session.current.active;
        const tab = index == null ? undefined : session.current.tabs[index];
        const target = tab ? watchOf(tab.view) : null;
        if (target) {
          void send({ setNamespace: { namespace: tab?.namespace ?? null } });
          void send({ watch: { target } });
        }
      }
      return;
    }
    if (key === "overview" && "overview" in event) {
      setOverview(event.overview);
    }
  };

  useEffect(() => {
    let stop = false;
    let unlisten: (() => void) | undefined;
    void listen<AppEvent>("kubi", (message) => {
      handleRef.current(message.payload);
    }).then((fn) => {
      if (stop) fn();
      else unlisten = fn;
    });
    void send("loadContexts");
    return () => {
      stop = true;
      unlisten?.();
    };
  }, []);

  useEffect(() => {
    if (active != null || !context) return;
    const id = window.setInterval(() => {
      void send("fetchOverview");
    }, 15000);
    return () => window.clearInterval(id);
  }, [active, context]);

  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (event.ctrlKey && !event.metaKey && !event.altKey && !event.shiftKey && event.key.toLowerCase() === "a") {
        if (!searchOpen) {
          event.preventDefault();
          setSearchOpen(true);
        }
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [searchOpen]);

  const activeTab = active == null ? null : (tabs[active] ?? null);

  return {
    contexts,
    context,
    namespaces,
    tabs,
    active,
    activeTab,
    home,
    customResources,
    error,
    loadingConfig,
    connecting,
    overview,
    metricsNote,
    history,
    searchOpen,
    createOpen,
    createYaml,
    createError,
    createBusy,
    pendingDelete,
    setError,
    switchContext,
    openKubeconfig: async () => {
      const picked = await open({ title: "Open kubeconfig", multiple: false, directory: false });
      if (typeof picked !== "string") return;
      session.current.context = null;
      setContext(null);
      setLoadingConfig(true);
      void send({ setKubeconfig: { path: picked } });
    },
    openView,
    closeTab: (index: number) => {
      const next = session.current.tabs.filter((_, i) => i !== index);
      const current = session.current.active;
      commitTabs(next);
      if (current == null) return;
      if (current > index) {
        session.current.active = current - 1;
        setActive(current - 1);
      } else if (current === index) {
        if (next.length === 0) {
          session.current.active = null;
          setActive(null);
          void send("stopWatch");
          void send("fetchOverview");
        } else {
          activate(Math.min(index, next.length - 1));
        }
      }
    },
    setNamespace: (namespace: string | null) => {
      const index = session.current.active;
      if (index == null) return;
      const tab = session.current.tabs[index];
      if (!tab || tab.namespace === namespace) return;
      session.current.lastNamespace = namespace;
      updateTabs((items) =>
        items.map((item, i) =>
          i === index
            ? {
                ...item,
                namespace,
                rows: [],
                selected: null,
                yaml: null,
                yamlFor: null,
                data: null,
                dataFor: null,
                waiting: true,
              }
            : item,
        ),
      );
      session.current.usage = {};
      setHistory([]);
      const target = watchOf(session.current.tabs[index]?.view ?? tab.view);
      void send({ setNamespace: { namespace } });
      if (target) void send({ watch: { target } });
    },
    setFilter: (filter: string) => {
      const index = session.current.active;
      if (index == null) return;
      updateTabs((items) => items.map((item, i) => (i === index ? { ...item, filter } : item)));
    },
    toggleSort: (sortKey: string) => {
      const index = session.current.active;
      if (index == null) return;
      updateTabs((items) =>
        items.map((item, i) => {
          if (i !== index) return item;
          if (item.sortKey === sortKey) return { ...item, sortAsc: !item.sortAsc };
          return { ...item, sortKey, sortAsc: true };
        }),
      );
    },
    selectRow: (uid: string) => selectUid(uid),
    setDetailTab: (detailTab: Tab["detailTab"]) => {
      const index = session.current.active;
      if (index == null) return;
      updateTabs((items) => items.map((item, i) => (i === index ? { ...item, detailTab } : item)));
    },
    setReveal: (reveal: boolean) => {
      const index = session.current.active;
      if (index == null) return;
      updateTabs((items) =>
        items.map((item, i) =>
          i === index ? { ...item, reveal, yaml: null, yamlFor: null, data: null, dataFor: null } : item,
        ),
      );
      requestYaml(index);
    },
    refresh: () => {
      void send("refreshCatalog");
      if (session.current.active == null) void send("fetchOverview");
      else activate(session.current.active);
    },
    askDelete: () => {
      const index = session.current.active;
      const tab = index == null ? undefined : session.current.tabs[index];
      const target = tab ? watchOf(tab.view) : null;
      const row = tab?.rows.find((item) => item.uid === tab.selected);
      if (!tab || !target || !row) return;
      setPendingDelete({
        title: viewTitle(tab.view),
        target,
        namespace: row.namespace,
        name: row.name,
      });
    },
    confirmDelete: () => {
      if (!pendingDelete) return;
      void send({
        delete: {
          target: pendingDelete.target,
          namespace: pendingDelete.namespace,
          name: pendingDelete.name,
        },
      });
      setPendingDelete(null);
    },
    cancelDelete: () => setPendingDelete(null),
    restartSelected: () => {
      const index = session.current.active;
      const tab = index == null ? undefined : session.current.tabs[index];
      const row = tab?.rows.find((item) => item.uid === tab.selected);
      if (!tab || tab.view.kind !== "resource" || !canRestart(tab.view.resource) || !row) return;
      void send({ restart: { kind: tab.view.resource, namespace: row.namespace, name: row.name } });
    },
    openCreate: () => {
      setCreateError(null);
      setCreateBusy(false);
      setCreateOpen(true);
    },
    setCreateYaml,
    closeCreate: () => {
      if (createBusy) return;
      setCreateOpen(false);
    },
    applyCreate: () => {
      const index = session.current.active;
      const tab = index == null ? undefined : session.current.tabs[index];
      setCreateBusy(true);
      setCreateError(null);
      void send({ apply: { yaml: createYaml, namespace: tab?.namespace ?? null } });
    },
    setSearchOpen,
    openArgoApp: (app: ArgoApp, target: CrTarget) => {
      const watch: WatchTarget = { custom: target };
      session.current.pending = { target: watch, namespace: app.namespace, name: app.name };
      openView({ kind: "custom", target });
      selectPending();
    },
  };
}

export type Kubi = ReturnType<typeof useKubi>;

:root {
  color: #dedede;
  background: #1e1e1e;
  font: 12px/1.4 ui-sans-serif, system-ui, sans-serif;
  --dock: #1e1e1e;
  --chrome: #323232;
  --field: #242424;
  --text: #dedede;
  --muted: #b2b2b2;
  --accent: #378ef0;
  --ok: #6ab07a;
  --warn: #e8b046;
  --bad: #ec5b62;
  --separator: #3e3e3e;
  --hover: #424242;
  --selected: #525252;
  --strip: #262626;
}

* { box-sizing: border-box; }
html, body, #root { height: 100%; margin: 0; }
button, input, textarea { font: inherit; color: inherit; }
button { background: transparent; border: 0; padding: 4px 8px; cursor: pointer; border-radius: 3px; }
button:hover { background: var(--hover); }
button:disabled { opacity: 0.5; cursor: default; }

.app {
  height: 100%;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-columns: 56px 236px minmax(0, 1fr);
  background: var(--dock);
}

.topbar {
  grid-column: 1 / -1;
  background: var(--chrome);
  border-bottom: 1px solid var(--separator);
  padding: 6px 10px;
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 36px;
}
.topbar .error { color: var(--bad); flex: 1; }
.spacer { flex: 1; }

.hotbar {
  background: var(--chrome);
  border-right: 1px solid var(--separator);
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.hotbar .chips {
