.table-wrap { flex: 1; overflow: auto; min-height: 0; }
table { border-collapse: separate; border-spacing: 0; min-width: 100%; }
th, td { text-align: left; padding: 0 8px; height: 28px; white-space: nowrap; font-weight: 400; }
