          </button>
          <button onClick={kubi.applyCreate} disabled={kubi.createBusy}>
            Apply
          </button>
        </div>
      </div>
    </div>
  );
}

export function DeleteModal({ kubi }: { kubi: Kubi }) {
  const pending = kubi.pendingDelete;
