export function RowMenu({ kubi }: { kubi: Kubi }) {
  const menu = kubi.menu;
  const tab = kubi.activeTab;
  const row = tab?.rows.find((item) => item.uid === menu?.uid);
  const kind = tab?.view.kind === "resource" ? tab.view.resource : null;
  useEffect(() => {
    if (!menu) return;
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") kubi.closeMenu();
    };
    window.addEventListener("keydown", onKey);
    window.addEventListener("mousedown", () => kubi.closeMenu());
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("mousedown", () => kubi.closeMenu());
    };
  }, [menu, kubi]);
  if (!menu || !row || !tab) return null;
  return (
    <div
      className="menu"
      style={{ left: Math.min(menu.x, window.innerWidth - 168), top: Math.min(menu.y, window.innerHeight - 132) }}
      onMouseDown={(event) => event.stopPropagation()}
    >
      {kind === "pods" ? (
        <button
          onClick={() => {
            kubi.closeMenu();
            kubi.openLogs();
          }}
        >
          <LogsIcon /> Logs
        </button>
      ) : null}
      {kind && canRestart(kind) ? (
        <button
          onClick={() => {
            kubi.closeMenu();
            kubi.restartSelected();
          }}
        >
          <RestartIcon /> Restart
        </button>
      ) : null}
      <button
        className="bad"
        onClick={() => {
          kubi.closeMenu();
          kubi.askDelete();
        }}
      >
        <TrashIcon /> Delete
      </button>
    </div>
  );
}

function LogsPane({ kubi, row }: { kubi: Kubi; row: ResourceRow }) {
  const logs = kubi.logs;
  const mine = logs && logs.namespace === row.namespace && logs.name === row.name ? logs : null;
  const box = useRef<HTMLPreElement>(null);
  const stick = useRef(true);
  useEffect(() => {
    const el = box.current;
    if (!el || !stick.current) return;
    el.scrollTop = el.scrollHeight;
  }, [mine?.lines]);
  return (
    <div className="logs">
      <div className="logs-bar">
        <select
          value={mine?.container ?? ""}
          disabled={!mine || mine.containers.length === 0}
          onChange={(event) => kubi.setLogContainer(event.target.value)}
        >
          {(mine?.containers ?? []).map((name) => (
            <option key={name} value={name}>
              {name}
            </option>
          ))}
        </select>
        {mine?.closed ? <span className="muted">stream closed</span> : null}
      </div>
      <pre
        ref={box}
        onScroll={(event) => {
          const el = event.currentTarget;
          stick.current = el.scrollHeight - el.scrollTop - el.clientHeight < 24;
        }}
      >
        {!mine || mine.id == null ? "Loading logs…" : mine.lines.join("\n")}
      </pre>
    </div>
  );
}

