const [logTabs, setLogTabsState] = useState<LogsView[]>([]);
const [activeLogId, setActiveLogIdState] = useState<number | null>(null);
const logsRef = useRef<LogsView[]>([]);
const activeLogRef = useRef<number | null>(null);
const logSeq = useRef(0);

function setLogTabs(next: LogsView[]) {
  logsRef.current = next;
  setLogTabsState(next);
}

function setActiveLog(id: number | null) {
  activeLogRef.current = id;
  setActiveLogIdState(id);
}

function haltLogs() {
  if (logsRef.current.length === 0) return;
  setLogTabs([]);
  setActiveLog(null);
  void send("stopLogs");
}

function sameLog(tab: LogsView, kind: ResourceKind, namespace: string, name: string) {
  return tab.kind === kind && tab.namespace === namespace && tab.name === name;
}

function beginStream(
  kind: ResourceKind,
  namespace: string,
  name: string,
  pod: string | null,
  container: string | null,
  previous: LogsView | null,
): LogsView {
  if (previous) void send({ stopLog: { id: previous.id } });
  logSeq.current += 1;
  const id = logSeq.current;
  const samePod = previous != null && (pod == null || pod === previous.pod);
  void send({ startLogs: { id, kind, namespace, name, pod, container } });
  return {
    id,
    kind,
    namespace,
    name,
    pods: previous ? previous.pods : [],
    pod: pod ?? previous?.pod ?? "",
    containers: samePod && previous ? previous.containers : [],
    container: container ?? (samePod && previous ? previous.container : ""),
    lines: [],
    started: false,
    closed: false,
  };
}

function openResourceLogs(kind: ResourceKind, namespace: string, name: string) {
  const existing = logsRef.current.find((tab) => sameLog(tab, kind, namespace, name));
  if (existing && !existing.closed) {
    setActiveLog(existing.id);
    return;
  }
  const tab = beginStream(kind, namespace, name, null, null, existing ?? null);
  setLogTabs(
    existing
      ? logsRef.current.map((item) => (item.id === existing.id ? tab : item))
      : [...logsRef.current, tab],
  );
  setActiveLog(tab.id);
}

function closeLog(id: number) {
  void send({ stopLog: { id } });
  const next = logsRef.current.filter((tab) => tab.id !== id);
  setLogTabs(next);
  if (activeLogRef.current === id) setActiveLog(next.at(-1)?.id ?? null);
}

