        WatchTarget::Custom(target) => {
            let resource =
                resource_of(&target.group, &target.version, &target.kind, &target.plural);
            delete_dynamic(client, &resource, target.namespaced, namespace, name).await
        }
    };
    if let Err(err) = result {
        self.emit_error(format!("delete {name}: {err}"));
    }
}

async fn restart(&self, kind: ResourceKind, namespace: &str, name: &str) {
    let Some(client) = self.current_client() else {
        self.emit_error("Not connected to a cluster");
        return;
    };
    if let Err(err) = restart_workload(client, kind, namespace, name).await {
        self.emit_error(format!("restart {name}: {err}"));
    }
}

async fn fetch_yaml(
    &self,
    target: WatchTarget,
    namespace: &str,
    name: &str,
    uid: &str,
    reveal_secrets: bool,
) {
    let Some(client) = self.current_client() else {
        self.emit_error("Not connected to a cluster");
        return;
    };
    let result = match &target {
        WatchTarget::Kind(kind) => {
            yaml_for(client.clone(), *kind, namespace, name, reveal_secrets).await
        }
        WatchTarget::Custom(target) => {
            let resource =
                resource_of(&target.group, &target.version, &target.kind, &target.plural);
            yaml_dynamic(
                client.clone(),
                &resource,
                target.namespaced,
                namespace,
                name,
            )
            .await
        }
    };
    match result {
        Ok(yaml) => self.emit(AppEvent::Yaml {
            uid: uid.to_string(),
            yaml,
        }),
        Err(err) => self.emit_error(err),
    }
    if let WatchTarget::Kind(kind) = &target {
        if kind.has_values() {
            let entries = object_entries(&client, *kind, namespace, name, reveal_secrets).await;
            match entries {
                Ok(entries) => self.emit(AppEvent::ObjectData {
                    uid: uid.to_string(),
                    entries,
                }),
                Err(err) => self.emit_error(err),
            }
        }
    }
}

