import { useEffect, useRef, useState, type MouseEvent as ReactMouseEvent, type PointerEvent as ReactPointerEvent, type ReactNode } from "react";
import { FitAddon } from "@xterm/addon-fit";
import { Terminal } from "@xterm/xterm";
import "@xterm/xterm/css/xterm.css";
import type { Kubi } from "./useKubi";

import { LogPane } from "./logWindow";

function usePressDrag() {
  const drag = useRef<{ token: number; x: number; y: number; moved: boolean } | null>(null);
  const skipClick = useRef(false);
  return {
    down(token: number, event: ReactPointerEvent) {
      if (event.button !== 0) return;
      skipClick.current = false;
      drag.current = { token, x: event.clientX, y: event.clientY, moved: false };
      event.currentTarget.setPointerCapture(event.pointerId);
    },
    move(event: ReactPointerEvent) {
      const state = drag.current;
      if (!state) return;
      if (Math.hypot(event.clientX - state.x, event.clientY - state.y) > 4) state.moved = true;
    },
    up(): number | null {
      const state = drag.current;
      drag.current = null;
      if (!state?.moved) return null;
      skipClick.current = true;
      return state.token;
    },
    cancel() {
      drag.current = null;
    },
    click(event: ReactMouseEvent): boolean {
      if (!skipClick.current) return false;
      skipClick.current = false;
      event.preventDefault();
      return true;
    },
  };
}

