export function ExecDrawer({ kubi }: { kubi: Kubi }) {
  const exec = kubi.exec;
  const host = useRef<HTMLDivElement>(null);
  const term = useRef<Terminal | null>(null);
  const api = useRef(kubi);
  api.current = kubi;
  useEffect(() => {
    const node = host.current;
    if (!exec || !node) return;
    const terminal = new Terminal({
      fontSize: 12,
      fontFamily: "ui-monospace, monospace",
      cursorBlink: true,
      theme: { background: "#1e1e1e", foreground: "#dedede", cursor: "#378ef0" },
    });
    const fit = new FitAddon();
    terminal.loadAddon(fit);
    terminal.open(node);
    fit.fit();
    term.current = terminal;
    api.current.execSink.current = (text) => terminal.write(text);
    const pending = api.current.takeExecPending();
    if (pending) terminal.write(pending);
    const input = terminal.onData((data) => api.current.execInput(data));
    const sendSize = () => {
      fit.fit();
      api.current.execResize(terminal.cols, terminal.rows);
    };
    sendSize();
    const observer = new ResizeObserver(sendSize);
    observer.observe(node);
    return () => {
      observer.disconnect();
      input.dispose();
      api.current.execSink.current = null;
      terminal.dispose();
      term.current = null;
    };
  }, [exec?.id]);
  if (!exec) return null;
  return (
    <section className="exec-drawer" aria-label="Exec">
      <header>
        <span className="name">
          {exec.namespace ? `${exec.namespace}/` : ""}
          {exec.name}
        </span>
        <select
          aria-label="Container"
          value={exec.container}
          disabled={exec.containers.length === 0}
          onChange={(event) => kubi.setExecContainer(event.target.value)}
        >
          {exec.containers.length === 0 ? <option value="" /> : null}
          {exec.containers.map((name) => (
            <option key={name} value={name}>
              {name}
            </option>
          ))}
        </select>
        {exec.closed ? <span className="muted">session closed</span> : null}
        <span className="spacer" />
        <button aria-label="Close exec" onClick={kubi.closeExec}>
          ×
        </button>
      </header>
      <div className="exec-term" ref={host} />
    </section>
  );
}

