    keep: impl Fn(&str) -> bool,
) -> Vec<(String, String)> {
    let mut pairs: Vec<_> = map
        .into_iter()
        .flatten()
        .filter(|(key, _)| keep(key))
        .map(|(key, value)| (key.clone(), value.clone()))
        .collect();
    pairs.sort();
    pairs
}

fn listener_lines(data: &serde_json::Value) -> String {
    let Some(items) = data
        .pointer("/spec/listeners")
        .and_then(|value| value.as_array())
    else {
        return String::new();
    };
    items
        .iter()
        .filter_map(listener_line)
        .collect::<Vec<_>>()
        .join("\n")
}

fn listener_line(item: &serde_json::Value) -> Option<String> {
    let name = item.get("name").and_then(|value| value.as_str()).unwrap_or("");
    let protocol = item
        .get("protocol")
        .and_then(|value| value.as_str())
        .unwrap_or("");
    let port = match item.get("port") {
        Some(serde_json::Value::Number(number)) => number.to_string(),
        Some(serde_json::Value::String(text)) => text.clone(),
        _ => String::new(),
    };
    let hostname = item
        .get("hostname")
        .and_then(|value| value.as_str())
        .unwrap_or("");
    let mut parts = Vec::new();
    if !name.is_empty() {
        parts.push(name.to_string());
    }
    if !protocol.is_empty() {
        parts.push(protocol.to_string());
    }
    if !port.is_empty() {
        parts.push(port);
    }
    if !hostname.is_empty() {
        parts.push(hostname.to_string());
    }
    if parts.is_empty() {
        None
    } else {
        Some(parts.join(" "))
    }
}

