type Fact = { kind: "text"; label: string; value: string } | { kind: "list"; label: string; items: string[] };

function shown(value: string | undefined): boolean {
  return value != null && value !== "" && value !== "-";
}

function textFact(label: string, value: string): Fact | null {
  if (!shown(value)) return null;
  return { kind: "text", label, value };
}

function listFact(label: string, raw: string, split: string): Fact | null {
  const items = raw
    .split(split)
    .map((item) => item.trim())
    .filter((item) => shown(item));
  if (items.length === 0) return null;
  return { kind: "list", label, items };
}

function keep(facts: Array<Fact | null>): Fact[] {
  return facts.filter((fact): fact is Fact => fact != null);
}

function cell(row: ResourceRow, key: string): string {
  return row.cells[key] ?? "";
}

function resourceFacts(kind: ResourceKind | null, row: ResourceRow): Fact[] {
  const cpu = formatCpuPair(row.cpuMillis, row.cpuRequestMillis);
  const memory = formatBytesPair(row.memBytes, row.memRequestBytes);
  switch (kind) {
    case "pods":
      return keep([
        textFact("Node", cell(row, "node")),
        textFact("Restarts", cell(row, "restarts")),
        textFact("CPU", cpu),
        textFact("Memory", memory),
      ]);
    case "deployments":
    case "replicaSets":
    case "statefulSets":
    case "daemonSets":
      return keep([textFact("Ready", row.ready)]);
    case "jobs":
      return keep([textFact("Completions", row.ready), textFact("Failed", row.info)]);
    case "cronJobs":
      return keep([
        textFact("Schedule", row.info),
        textFact("Suspend", row.status),
        textFact("Active", row.ready),
      ]);
    case "services":
      return keep([
        textFact("Type", row.status),
        textFact("Cluster IP", row.ready),
        textFact("Ports", row.info),
      ]);
    case "ingresses":
      return keep([textFact("Class", row.ready), textFact("Hosts", row.info)]);
    case "gateways":
      return keep([
        textFact("Class", cell(row, "class")),
        listFact("Addresses", cell(row, "addresses"), ","),
        listFact("Listeners", cell(row, "listenerList"), "\n"),
      ]);
    case "httpRoutes":
    case "grpcRoutes":
    case "tlsRoutes":
      return keep([textFact("Hostnames", cell(row, "hostnames")), textFact("Parent", cell(row, "parent"))]);
    case "tcpRoutes":
    case "udpRoutes":
      return keep([textFact("Parent", cell(row, "parent")), textFact("Backends", cell(row, "backends"))]);
    case "listenerSets":
      return keep([
        textFact("Gateway", cell(row, "gateway")),
        listFact("Listeners", cell(row, "listenerList"), "\n"),
      ]);
    case "backendTLSPolicies":
      return keep([textFact("Target", cell(row, "target")), textFact("Hostname", cell(row, "hostname"))]);
    case "referenceGrants":
      return keep([textFact("From", cell(row, "from")), textFact("To", cell(row, "to"))]);
    case "nodes":
      return keep([
        textFact("Roles", row.info),
        textFact("Kubelet", row.ready),
        textFact("CPU", cpu),
        textFact("Memory", memory),
      ]);
    case "configMaps":
      return keep([textFact("Keys", row.ready), textFact("Data", row.info)]);
    case "secrets":
      return keep([textFact("Type", row.status), textFact("Keys", row.ready)]);
    case "persistentVolumeClaims":
    case "persistentVolumes":
      return keep([
        textFact("Phase", row.status),
        textFact("Size", row.ready),
        textFact("Class", cell(row, "class")),
      ]);
    case "storageClasses":
      return keep([textFact("Provisioner", row.info), textFact("Reclaim", row.ready)]);
    case "serviceAccounts":
      return keep([textFact("Secrets", row.ready), textFact("Pull secrets", row.info)]);
    case "roles":
    case "clusterRoles":
      return keep([textFact("Rules", row.ready)]);
    case "roleBindings":
    case "clusterRoleBindings":
      return keep([textFact("Subjects", row.ready), textFact("Role", row.info)]);
    case "namespaces":
      return keep([textFact("Phase", row.status)]);
    case "events":
      return keep([
        textFact("Reason", cell(row, "reason")),
        textFact("Object", cell(row, "object")),
        textFact("Count", cell(row, "count")),
        textFact("Message", cell(row, "message")),
      ]);
    case "horizontalPodAutoscalers":
      return keep([textFact("Replicas", row.ready), textFact("Target", row.info)]);
    case "podDisruptionBudgets":
      return keep([textFact("Healthy", row.ready), textFact("Budget", row.info)]);
    case "networkPolicies":
      return keep([textFact("Types", row.ready), textFact("Rules", row.info)]);
    case "resourceQuotas":
      return keep([textFact("Used", row.ready), textFact("Hard", row.info)]);
    case "limitRanges":
      return keep([textFact("Limits", row.ready), textFact("Types", row.info)]);
    case "endpoints":
      return keep([textFact("Addresses", row.ready), textFact("Not ready", row.info)]);
    case "endpointSlices":
      return keep([textFact("Address type", row.status), textFact("Endpoints", row.ready)]);
    case "customResourceDefinitions":
      return keep([textFact("Scope", row.ready), textFact("Group", row.info)]);
    case "gatewayClasses":
    case "ingressClasses":
      return keep([textFact("Controller", kind === "gatewayClasses" ? cell(row, "controller") : row.ready)]);
    default:
      return keep([
        textFact("Info", row.info),
        ...Object.entries(row.cells).map(([key, value]) => textFact(key, value)),
      ]);
  }
}

