  const wait = Math.max(0, 400 - (Date.now() - refreshStarted.current));
  if (refreshTimer.current != null) window.clearTimeout(refreshTimer.current);
  refreshTimer.current = window.setTimeout(() => {
    refreshTimer.current = null;
    setRefreshing(false);
  }, wait);
}

