fn managed_by(meta: &ObjectMeta) -> String {
    let owners = meta.owner_references.as_deref().unwrap_or(&[]);
    let controllers: Vec<_> = owners
        .iter()
        .filter(|owner| owner.controller == Some(true))
        .collect();
    let chosen: Vec<_> = if controllers.is_empty() {
        owners.iter().collect()
    } else {
        controllers
    };
    if !chosen.is_empty() {
        return chosen
            .into_iter()
            .map(|owner| format!("{}/{}", owner.kind, owner.name))
            .collect::<Vec<_>>()
            .join(", ");
    }
    meta.labels
        .as_ref()
        .and_then(|labels| labels.get("app.kubernetes.io/managed-by"))
        .filter(|value| !value.is_empty())
        .cloned()
        .unwrap_or_default()
}

